<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Task Manager</title>
  <link rel="stylesheet" href="styles.css">
</head>
<body>

  <!-- ==================== HEADER ==================== -->
  <header>
    <h1>📋 Task Manager</h1>
    <p>Stay organized, stay productive</p>
  </header>

  <!-- ==================== ADD TASK FORM ==================== -->
  <section class="add-task-section">
    <h2>Add New Task</h2>
    <form id="task-form" novalidate>
      <div class="form-group">
        <label for="task-title">Title *</label>
        <input
          type="text"
          id="task-title"
          placeholder="Enter task title..."
          maxlength="100"
          required
        >
      </div>
      <div class="form-group">
        <label for="task-desc">Description</label>
        <textarea
          id="task-desc"
          placeholder="Enter a description (optional)..."
          maxlength="500"
          rows="3"
        ></textarea>
      </div>
      <button type="submit" id="add-task-btn">+ Add Task</button>
    </form>
    <!-- Error message displayed below the form -->
    <p id="form-error" class="error-msg"></p>
  </section>

  <!-- ==================== FILTER BAR ==================== -->
  <section class="filter-section">
    <h2>Filter Tasks</h2>
    <div class="filter-buttons">
      <button class="filter-btn active" data-filter="all">All</button>
      <button class="filter-btn" data-filter="pending">Pending</button>
      <button class="filter-btn" data-filter="in_progress">In Progress</button>
      <button class="filter-btn" data-filter="completed">Completed</button>
    </div>
  </section>

  <!-- ==================== TASK BOARD (GROUPED BY STATUS) ==================== -->
  <main id="task-board">
    <!-- Pending Column -->
    <section class="column" data-status="pending">
      <h2 class="column-header status-pending">
        <span class="status-dot status-pending"></span>
        Pending
        <span class="count-badge" id="count-pending">0</span>
      </h2>
      <div class="task-list" id="list-pending"></div>
    </section>

    <!-- In Progress Column -->
    <section class="column" data-status="in_progress">
      <h2 class="column-header status-in_progress">
        <span class="status-dot status-in_progress"></span>
        In Progress
        <span class="count-badge" id="count-in_progress">0</span>
      </h2>
      <div class="task-list" id="list-in_progress"></div>
    </section>

    <!-- Completed Column -->
    <section class="column" data-status="completed">
      <h2 class="column-header status-completed">
        <span class="status-dot status-completed"></span>
        Completed
        <span class="count-badge" id="count-completed">0</span>
      </h2>
      <div class="task-list" id="list-completed"></div>
    </section>
  </main>

  <!-- ==================== EMPTY STATE (shown when no tasks match) ==================== -->
  <div id="empty-state" class="empty-state hidden">
    <p>No tasks to display.</p>
  </div>

  <script src="app.js"></script>
