## `app.js`

```javascript
/**
 * =============================================
 * TASK MANAGEMENT APPLICATION
 * =============================================
 * A vanilla JavaScript app that manages tasks
 * with add, toggle, delete, filter, and persist
 * features using localStorage.
 * =============================================
 */

// ==================== STATE MANAGEMENT ====================

/**
 * Application state object.
 * Holds the current list of tasks and the active filter.
 */
const state = {
  tasks: [],       // Array of task objects
  filter: 'all',   // Current filter: 'all' | 'pending' | 'in_progress' | 'completed'
};

// ==================== LOCAL STORAGE ====================

/**
 * Key used in localStorage for task persistence.
 */
const STORAGE_KEY = 'task_manager_tasks';

/**
 * Load tasks from localStorage on app initialization.
 * Falls back to an empty array if no data is found.
 */
function loadTasks() {
  try {
    const stored = localStorage.getItem(STORAGE_KEY);
    state.tasks = stored ? JSON.parse(stored) : [];
  } catch (e) {
    console.error('Failed to load tasks from localStorage:', e);
    state.tasks = [];
  }
}

/**
 * Save the current tasks array to localStorage.
 */
function saveTasks() {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(state.tasks));
  } catch (e) {
    console.error('Failed to save tasks to localStorage:', e);
  }
}

// ==================== TASK CRUD OPERATIONS ====================

/**
 * Generate a unique ID for a new task.
 * Uses timestamp + random suffix to avoid collisions.
 */
function generateId() {
  return Date.now().toString(36) + Math.random().toString(36).substr(2, 5);
}

/**
 * Format a date string into a readable format (e.g., "Jan 15, 2025").
 * @param {string} isoDate - ISO date string from task creation.
 * @returns {string} Formatted date string.
 */
function formatDate(isoDate) {
  const date = new Date(isoDate);
  return date.toLocaleDateString('en-US', {
    month: 'short',
    day: 'numeric',
    year: 'numeric',
  });
}

/**
 * Add a new task to the state and persist it.
 * @param {string} title - Task title (required).
 * @param {string} description - Task description (optional).
 */
function addTask(title, description) {
  const task = {
    id: generateId(),
    title: title.trim(),
    description: description.trim(),
    status: 'pending', // Default status
    createdAt: new Date().toISOString(),
  };

  state.tasks.push(task);
  saveTasks();
}

/**
 * Toggle a task's status between pending → in_progress → completed → pending.
 * @param {string} taskId - The ID of the task to toggle.
 */
function toggleTask(taskId) {
  const task = state.tasks.find((t) => t.id === taskId);
  if (!task) return;

  // Cycle through statuses: pending → in_progress → completed → pending
  const statusOrder = ['pending', 'in_progress', 'completed'];
  const currentIndex = statusOrder.indexOf(task.status);
  task.status = statusOrder[(currentIndex + 1) % statusOrder.length];

  saveTasks();
}

/**
 * Delete a task by its ID and persist the change.
 * @param {string} taskId - The ID of the task to delete.
 */
function deleteTask(taskId) {
  state.tasks = state.tasks.filter((t) => t.id !== taskId);
  saveTasks();
}

// ==================== FILTERING ====================

/**
 * Get tasks filtered by the current filter setting.
 * @returns {Array} Filtered task array.
 */
function getFilteredTasks() {
  if (state.filter === 'all') return state.tasks;
  return state.tasks.filter((t) => t.status === state.filter);
}

/**
 * Count tasks in each status category for the count badges.
 * @returns {Object} Object with counts per status.
 */
function getCounts() {
  const counts = { pending: 0, in_progress: 0, completed: 0 };
  state.tasks.forEach((t) => {
    if (counts[t.status] !== undefined) counts[t.status]++;
  });
  return counts;
}

// ==================== DOM REFERENCES ====================

/**
 * Cache all DOM elements we'll interact with to avoid
 * repeated querySelector calls during rendering.
 */
const dom = {
  form: document.getElementById('task-form'),
  titleInput: document.getElementById('task-title'),
  descInput: document.getElementById('task-desc'),
  errorMsg: document.getElementById('form-error'),
  filterBtns: document.querySelectorAll('.filter-btn'),
  taskBoard: document.getElementById('task-board'),
  emptyState: document.getElementById('empty-state'),
  countPending: document.getElementById('count-pending'),
  countInProgress: document.getElementById('count-in_progress'),
  countCompleted: document.getElementById('count-completed'),
};

// ==================== RENDERING ====================

/**
 * Render the entire task board based on current state.
 * This is the main render function called after any state change.
 */
function render() {
  renderCounts();
  renderTasks();
  renderEmptyState();
}

/**
 * Update the count badges in each column header.
 */
function renderCounts() {
  const counts = getCounts();
  dom.countPending.textContent = counts.pending;
  dom.countInProgress.textContent = counts.in_progress;
  dom.countCompleted.textContent = counts.completed;
}

/**
 * Render task cards into their respective columns.
 * Only shows tasks matching the current filter.
 */
function renderTasks() {
  const filtered = getFilteredTasks();

  // Group filtered tasks by status for rendering
  const grouped = { pending: [], in_progress: [], completed: [] };
  filtered.forEach((task) => {
    if (grouped[task.status]) {
      grouped[task.status].push(task);
    }
  });

  // Render each column
  ['pending', 'in_progress', 'completed'].forEach((status) => {
    const list = document.getElementById(`list-${status}`);
    const tasks = grouped[status];

    // Clear existing cards
    list.innerHTML = '';

    // Create and append task cards
    tasks.forEach((task) => {
      list.appendChild(createTaskCard(task));
    });
  });
}

/**
 * Show or hide the empty state message.
 */
function renderEmptyState() {
  const filtered = getFilteredTasks();
  if (filtered.length === 0) {
    dom.emptyState.classList.remove('hidden');
  } else {
    dom.emptyState.classList.add('hidden');
  }
}

/**
 * Create a DOM element for a single task card.
 * @param {Object} task - The task object.
 * @returns {HTMLElement} The task card element.
 */
function createTaskCard(task) {
  const card = document.createElement('div');
  card.className = `task-card ${task.status === 'completed' ? 'completed' : ''}`;
  card.dataset.status = task.status;
  card.dataset.id = task.id;

  // Title
  const titleEl = document.createElement('p');
  titleEl.className = 'task-title';
  titleEl.textContent = task.title;

  // Description (only if it exists)
  let descEl = null;
  if (task.description) {
    descEl = document.createElement('p');
    descEl.className = 'task-desc';
    descEl.textContent = task.description;
  }

  // Meta row: date + delete button
  const metaEl = document.createElement('div');
  metaEl.className = 'task-meta';

  const dateEl = document.createElement('span');
  dateEl.className = 'task-date';
  dateEl.textContent = formatDate(task.createdAt);

  const deleteBtn = document.createElement('button');
  deleteBtn.className = 'delete-btn';
  deleteBtn.innerHTML = '🗑️';
  deleteBtn.title = 'Delete task';
  deleteBtn.addEventListener('click', (e) => {
    e.stopPropagation(); // Prevent toggling when deleting
    deleteTask(task.id);
    render();
  });

  metaEl.appendChild(dateEl);
  metaEl.appendChild(deleteBtn);

  // Assemble the card
  card.appendChild(titleEl);
  if (descEl) card.appendChild(descEl);
  card.appendChild(metaEl);

  // Clicking the card toggles its status
  card.addEventListener('click', () => {
    toggleTask(task.id);
    render();
  });

  return card;
}

// ==================== EVENT LISTENERS ====================

/**
 * Handle form submission to add a new task.
 * Validates that the title is not empty before adding.
 */
dom.form.addEventListener('submit', (e) => {
  e.preventDefault();

  const title = dom.titleInput.value.trim();
  const description = dom.descInput.value.trim();

  // Clear previous error
  dom.errorMsg.textContent = '';

  // Validate title
  if (!title) {
    dom.errorMsg.textContent = 'Please enter a task title.';
    dom.titleInput.focus();
    return;
  }

  // Add the task and reset the form
  addTask(title, description);
  dom.form.reset();
  dom.titleInput.focus();
});

/**
 * Handle filter button clicks.
 * Updates the active filter and re-renders the board.
 */
dom.filterBtns.forEach((btn) => {
  btn.addEventListener('click', () => {
    // Remove active class from all buttons
    dom.filterBtns.forEach((b) => b.classList.remove('active'));
    // Add active class to clicked button
    btn.classList.add('active');

    // Update state and re-render
    state.filter = btn.dataset.filter;
    render();
  });
});

// ==================== INITIALIZATION ====================

/**
 * Initialize the application:
 * 1. Load tasks from localStorage
 * 2. Render the initial UI
 */
function init() {
  loadTasks();
  render();
}

// Start the app when the DOM is ready
init();
