## `index.html`

```html
<!DOCTYPE html>
<html lang="pt-BR">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Gerenciador de Tarefas</title>
  <link rel="stylesheet" href="styles.css">
</head>
<body>

  <!-- ==================== CABEÇALHO ==================== -->
  <header>
    <h1>📋 Gerenciador de Tarefas</h1>
    <p class="subtitle">Organize suas tarefas de forma simples e eficiente</p>
  </header>

  <main>

    <!-- ==================== FORMULÁRIO DE ADIÇÃO ==================== -->
    <section class="add-task-section" aria-label="Adicionar nova tarefa">
      <h2>➕ Nova Tarefa</h2>
      <form id="task-form" novalidate>
        <div class="form-group">
          <label for="task-title">Título *</label>
          <input
            type="text"
            id="task-title"
            placeholder="Digite o título da tarefa"
            maxlength="100"
            required
          >
        </div>
        <div class="form-group">
          <label for="task-desc">Descrição</label>
          <textarea
            id="task-desc"
            placeholder="Digite a descrição (opcional)"
            maxlength="500"
            rows="3"
          ></textarea>
        </div>
        <button type="submit" class="btn-add">Adicionar Tarefa</button>
      </form>
    </section>

    <!-- ==================== FILTROS ==================== -->
    <section class="filters-section" aria-label="Filtros de tarefas">
      <h2>🔍 Filtros</h2>
      <div class="filter-buttons" role="group">
        <button class="btn-filter active" data-filter="todas">Todas</button>
        <button class="btn-filter" data-filter="pendente">⏳ Pendentes</button>
        <button class="btn-filter" data-filter="em_andamento">🔄 Em Andamento</button>
        <button class="btn-filter" data-filter="concluído">✅ Concluídos</button>
      </div>
    </section>

    <!-- ==================== LISTA DE TAREFAS ==================== -->
    <section class="tasks-section" aria-label="Lista de tarefas">
      <h2>📝 Tarefas</h2>

      <!-- Seção: Pendentes -->
      <div class="task-group" id="group-pendente">
        <h3 class="group-title pendente">⏳ Pendentes</h3>
        <ul class="task-list" id="list-pendente"></ul>
      </div>

      <!-- Seção: Em Andamento -->
      <div class="task-group" id="group-em_andamento">
        <h3 class="group-title em_andamento">🔄 Em Andamento</h3>
        <ul class="task-list" id="list-em_andamento"></ul>
      </div>

      <!-- Seção: Concluídos -->
      <div class="task-group" id="group-concluído">
        <h3 class="group-title concluído">✅ Concluídos</h3>
        <ul class="task-list" id="list-concluído"></ul>
      </div>

      <!-- Mensagem quando não há tarefas -->
      <p class="empty-message" id="empty-message" style="display: none;">
        Nenhuma tarefa encontrada. Adicione uma nova! 🎉
      </p>
    </section>

  </main>

  <!-- ==================== RODAPÉ ==================== -->
  <footer>
    <p>Gerenciador de Tarefas &copy; 2025 — Dados salvos localmente no navegador.</p>
  </footer>

  <script src="app.js"></script>
</body>
</html>
