## `app.js`

```javascript
/* ============================================================
   GERENCIADOR DE TAREFAS — app.js
   Aplicação completa em JavaScript puro (vanilla JS)
   ============================================================ */

// ==================== ESTADO DA APLICAÇÃO ====================
/**
 * Array principal de tarefas. Cada tarefa é um objeto com:
 *   - id: string única (timestamp)
 *   - title: string
 *   - description: string
 *   - status: 'pendente' | 'em_andamento' | 'concluído'
 *   - createdAt: timestamp de criação
 */
let tasks = [];

/** Filtro atual aplicado à visualização */
let currentFilter = 'todas';

// ==================== CONSTANTES E SELECTORS DO DOM ====================
const DOM = {
  // Formulário
  form:          document.getElementById('task-form'),
  titleInput:    document.getElementById('task-title'),
  descInput:     document.getElementById('task-desc'),

  // Filtros
  filterButtons: document.querySelectorAll('.btn-filter'),

  // Listas por status
  lists: {
    'pendente':      document.getElementById('list-pendente'),
    'em_andamento':  document.getElementById('list-em_andamento'),
    'concluído':     document.getElementById('list-concluído'),
  },

  // Grupos (seções) por status
  groups: {
    'pendente':      document.getElementById('group-pendente'),
    'em_andamento':  document.getElementById('group-em_andamento'),
    'concluído':     document.getElementById('group-concluído'),
  },

  // Mensagem vazia
  emptyMessage: document.getElementById('empty-message'),
};

// ==================== PERSISTÊNCIA COM LOCALSTORAGE ====================
/**
 * Salva o array de tarefas no localStorage do navegador.
 * Usamos JSON.stringify/parse para converter entre objeto e string.
 */
function saveTasks() {
  localStorage.setItem('taskManager_tasks', JSON.stringify(tasks));
}

/**
 * Carrega as tarefas salvas no localStorage.
 * Se não houver dados, retorna array vazio.
 */
function loadTasks() {
  const stored = localStorage.getItem('taskManager_tasks');
  if (stored) {
    try {
      tasks = JSON.parse(stored);
    } catch (e) {
      console.error('Erro ao carregar tarefas:', e);
      tasks = [];
    }
  }
}

// ==================== FUNÇÕES DE UTILIDADE ====================
/**
 * Gera um ID único para cada tarefa usando timestamp.
 */
function generateId() {
  return Date.now().toString(36) + Math.random().toString(36).substr(2, 5);
}

/**
 * Retorna a data/hora formatada de forma legível.
 */
function formatDate(timestamp) {
  return new Date(timestamp).toLocaleDateString('pt-BR', {
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
  });
}

// ==================== OPERAÇÕES CRUD ====================
/**
 * CRIA — Adiciona uma nova tarefa ao estado e salva.
 */
function addTask(title, description) {
  const task = {
    id: generateId(),
    title: title.trim(),
    description: description.trim(),
    status: 'pendente', // Status inicial padrão
    createdAt: Date.now(),
  };

  tasks.push(task);
  saveTasks();
  renderTasks();
}

/**
 * EXCLUI — Remove uma tarefa pelo ID, com animação.
 */
function deleteTask(id) {
  const taskEl = document.querySelector(`[data-id="${id}"]`);

  // Se o elemento existe, aplica animação de saída antes de remover
  if (taskEl) {
    taskEl.classList.add('removing');
    taskEl.addEventListener('animationend', () => {
      tasks = tasks.filter(t => t.id !== id);
      saveTasks();
      renderTasks();
    }, { once: true });
  } else {
    // Fallback caso o elemento já não esteja no DOM
    tasks = tasks.filter(t => t.id !== id);
    saveTasks();
    renderTasks();
  }
}

/**
 * ALTERA STATUS — Cicla entre os três status ao clicar na tarefa.
 * Ordem: pendente → em_andamento → concluído → pendente
 */
function toggleTaskStatus(id) {
  const task = tasks.find(t => t.id === id);
  if (!task) return;

  // Mapeia a ordem dos status
  const statusOrder = ['pendente', 'em_andamento', 'concluído'];
  const currentIndex = statusOrder.indexOf(task.status);
  const nextIndex = (currentIndex + 1) % statusOrder.length;
  task.status = statusOrder[nextIndex];

  saveTasks();
  renderTasks();
}

// ==================== RENDERIZAÇÃO ====================
/**
 * Renderiza todas as tarefas agrupadas por status.
 * Aplica o filtro atual para mostrar/ocultar grupos.
 */
function renderTasks() {
  // Limpa todas as listas
  Object.values(DOM.lists).forEach(list => list.innerHTML = '');

  // Agrupa tarefas pelo status
  const grouped = {
    'pendente':      [],
    'em_andamento':  [],
    'concluído':     [],
  };

  tasks.forEach(task => {
    if (grouped[task.status]) {
      grouped[task.status].push(task);
    }
  });

  // Ordena: mais recentes primeiro dentro de cada grupo
  Object.values(grouped).forEach(arr => arr.sort((a, b) => b.createdAt - a.createdAt));

  // Determina quais grupos mostrar com base no filtro
  const visibleStatuses = getVisibleStatuses();

  let totalVisible = 0;

  Object.keys(DOM.groups).forEach(status => {
    const groupEl = DOM.groups[status];
    const listEl = DOM.lists[status];
    const taskItems = grouped[status];

    // Mostra ou esconde o grupo inteiro baseado no filtro
    if (visibleStatuses.includes(status) || currentFilter === 'todas') {
      groupEl.style.display = '';

      // Renderiza cada tarefa como um card HTML
      taskItems.forEach(task => {
        const li = createTaskElement(task);
        listEl.appendChild(li);
        totalVisible++;
      });
    } else {
      groupEl.style.display = 'none';
    }
  });

  // Mostra/esconde a mensagem de lista vazia
  DOM.emptyMessage.style.display = totalVisible === 0 ? 'block' : 'none';
}

/**
 * Cria o elemento HTML (li) para uma tarefa individual.
 */
function createTaskElement(task) {
  const li = document.createElement('li');
  li.className = `task-item ${task.status}`;
  li.setAttribute('data-id', task.id);
  li.setAttribute('title', `Clique para alterar o status`);

  // Badge colorido no canto superior direito
  const badge = `<span class="status-badge ${task.status}"></span>`;

  // Descrição truncada se muito longa
  const descText = task.description
    ? `<p class="task-desc">${escapeHtml(task.description)}</p>`
    : '';

  li.innerHTML = `
    ${badge}
    <div class="task-checkbox"></div>
    <div class="task-content">
      <h4 class="task-title">${escapeHtml(task.title)}</h4>
      ${descText}
      <span class="task-date" style="font-size:0.75rem;color:var(--color-text-muted);margin-top:0.25rem;display:block;">
        Criada em ${formatDate(task.createdAt)}
      </span>
    </div>
    <button
      class="btn-delete"
      title="Excluir tarefa"
      aria-label="Excluir tarefa: ${escapeHtml(task.title)}"
    >✕</button>
  `;

  // Evento de clique no card — altera o status
  li.addEventListener('click', (e) => {
    // Não altera o status se o usuário clicou no botão excluir
    if (!e.target.closest('.btn-delete')) {
      toggleTaskStatus(task.id);
    }
  });

  // Evento de clique no botão excluir
  const deleteBtn = li.querySelector('.btn-delete');
  deleteBtn.addEventListener('click', (e) => {
    e.stopPropagation(); // Impede que o clique propague para o card
    deleteTask(task.id);
  });

  return li;
}

/**
 * Retorna os status visíveis com base no filtro atual.
 */
function getVisibleStatuses() {
  if (currentFilter === 'todas') return ['pendente', 'em_andamento', 'concluído'];
  return [currentFilter];
}

/**
 * Escapa caracteres HTML para prevenir XSS.
 */
function escapeHtml(text) {
  const div = document.createElement('div');
  div.textContent = text;
  return div.innerHTML;
}

// ==================== EVENT LISTENERS ====================
/**
 * Submissão do formulário — adiciona nova tarefa.
 */
DOM.form.addEventListener('submit', (e) => {
  e.preventDefault();

  const title = DOM.titleInput.value.trim();
  const description = DOM.descInput.value.trim();

  // Validação básica
  if (!title) {
    DOM.titleInput.focus();
    DOM.titleInput.style.borderColor = 'var(--color-danger)';
    setTimeout(() => {
      DOM.titleInput.style.borderColor = '';
    }, 2000);
    return;
  }

  addTask(title, description);

  // Limpa o formulário após adicionar
  DOM.form.reset();
  DOM.titleInput.focus();
});

/**
 * Foco no input de título — remove borda vermelha se existir.
 */
DOM.titleInput.addEventListener('focus', () => {
  DOM.titleInput.style.borderColor = '';
});

/**
 * Cliques nos botões de filtro.
 */
DOM.filterButtons.forEach(btn => {
  btn.addEventListener('click', () => {
    // Remove classe active de todos os botões
    DOM.filterButtons.forEach(b => b.classList.remove('active'));
    // Adiciona classe active ao botão clicado
    btn.classList.add('active');

    // Atualiza o filtro e re-renderiza
    currentFilter = btn.dataset.filter;
    renderTasks();
  });
});

// ==================== INICIALIZAÇÃO ====================
/**
 * Carrega as tarefas salvas e faz a primeira renderização.
 */
function init() {
  loadTasks();
  renderTasks();
  console.log(`📋 Tarefas carregadas: ${tasks.length}`);
}

// Inicia a aplicação quando o DOM estiver pronto
init();
