## app.js

```javascript
/**
 * ========================================
 * TASK MANAGER APPLICATION
 * ========================================
 * A vanilla JavaScript task management app with:
 *   - Add / delete / cycle task status
 *   - Grouped board view (Pending, In Progress, Completed)
 *   - Filter bar to show tasks by status
 *   - localStorage persistence
 * ========================================
 */

// ──────────────────────────────────────────
// 1. STATE MANAGEMENT
// ──────────────────────────────────────────

/** Current filter applied ('all', 'pending', 'in_progress', 'completed') */
let currentFilter = 'all';

/** Array of task objects stored in memory and localStorage */
let tasks = [];

// ──────────────────────────────────────────
// 2. LOCAL STORAGE HELPERS
// ──────────────────────────────────────────

const STORAGE_KEY = 'task_manager_tasks';

/**
 * Load tasks from localStorage on app startup.
 * Falls back to an empty array if nothing is stored.
 */
function loadTasks() {
  try {
    const stored = localStorage.getItem(STORAGE_KEY);
    tasks = stored ? JSON.parse(stored) : [];
  } catch (e) {
    console.error('Failed to load tasks from localStorage:', e);
    tasks = [];
  }
}

/**
 * Save the current tasks array to localStorage.
 */
function saveTasks() {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(tasks));
  } catch (e) {
    console.error('Failed to save tasks to localStorage:', e);
  }
}

// ──────────────────────────────────────────
// 3. TASK CRUD OPERATIONS
// ──────────────────────────────────────────

/**
 * Generate a unique ID for new tasks using timestamp + random suffix.
 */
function generateId() {
  return Date.now().toString(36) + Math.random().toString(36).substr(2, 5);
}

/**
 * Add a new task to the board.
 * @param {string} title - Task title (required)
 * @param {string} description - Task description (optional)
 * @returns {object} The newly created task
 */
function addTask(title, description = '') {
  const task = {
    id: generateId(),
    title: title.trim(),
    description: description.trim(),
    status: 'pending', // default status
    createdAt: new Date().toISOString()
  };

  tasks.push(task);
  saveTasks();
  return task;
}

/**
 * Delete a task by its ID.
 * @param {string} taskId - The unique task identifier
 */
function deleteTask(taskId) {
  tasks = tasks.filter(t => t.id !== taskId);
  saveTasks();
}

/**
 * Cycle a task's status: pending → in_progress → completed → pending
 * @param {string} taskId - The unique task identifier
 */
function cycleTaskStatus(taskId) {
  const task = tasks.find(t => t.id === taskId);
  if (!task) return;

  const statusOrder = ['pending', 'in_progress', 'completed'];
  const currentIndex = statusOrder.indexOf(task.status);
  // Cycle to the next status (wrap around)
  task.status = statusOrder[(currentIndex + 1) % statusOrder.length];
  saveTasks();
}

// ──────────────────────────────────────────
// 4. RENDERING — BOARD & TASK CARDS
// ──────────────────────────────────────────

/**
 * Render the entire task board based on current filter and tasks state.
 * Clears all columns, then repopulates them.
 */
function renderBoard() {
  // Get references to each column's task list container
  const pendingList = document.getElementById('list-pending');
  const inProgressList = document.getElementById('list-in_progress');
  const completedList = document.getElementById('list-completed');

  // Clear existing content
  pendingList.innerHTML = '';
  inProgressList.innerHTML = '';
  completedList.innerHTML = '';

  // Filter tasks based on current filter setting
  const filteredTasks = tasks.filter(task => {
    if (currentFilter === 'all') return true;
    return task.status === currentFilter;
  });

  // Group filtered tasks by status for rendering
  const pendingTasks = filteredTasks.filter(t => t.status === 'pending');
  const inProgressTasks = filteredTasks.filter(t => t.status === 'in_progress');
  const completedTasks = filteredTasks.filter(t => t.status === 'completed');

  // Render task cards into each column
  renderTaskCards(pendingTasks, pendingList);
  renderTaskCards(inProgressTasks, inProgressList);
  renderTaskCards(completedTasks, completedList);

  // Update count badges for each column (based on ALL tasks, not filtered)
  updateCountBadges();

  // Show/hide empty state message
  toggleEmptyState(tasks.length === 0);
}

/**
 * Render an array of task cards into a given container.
 * @param {Array} taskList - Array of task objects to render
 * @param {HTMLElement} container - The DOM element to append cards to
 */
function renderTaskCards(taskList, container) {
  if (taskList.length === 0) return;

  taskList.forEach(task => {
    const card = createTaskCard(task);
    container.appendChild(card);
  });
}

/**
 * Create a DOM element representing a single task card.
 * @param {object} task - The task data object
 * @returns {HTMLElement} The task card div
 */
function createTaskCard(task) {
  const card = document.createElement('div');
  card.className = 'task-card';
  card.dataset.status = task.status;
  card.dataset.id = task.id;

  // Format the status label for display
  const statusLabel = task.status.replace('_', ' ');

  // Build the card HTML
  card.innerHTML = `
    <div class="task-title">${escapeHtml(task.title)}</div>
    ${task.description ? `<div class="task-desc">${escapeHtml(task.description)}</div>` : ''}
    <div class="task-footer">
      <span class="status-label ${task.status}">${statusLabel}</span>
      <span class="cycle-hint" title="Click to change status">↻ click to cycle</span>
      <button class="btn-delete" title="Delete task" aria-label="Delete task">🗑️</button>
    </div>
  `;

  // ── Event: Click card to cycle status ──
  card.addEventListener('click', (e) => {
    // Don't trigger if user clicked the delete button
    if (e.target.closest('.btn-delete')) return;
    cycleTaskStatus(task.id);
    renderBoard();
  });

  // ── Event: Click delete button ──
  const deleteBtn = card.querySelector('.btn-delete');
  deleteBtn.addEventListener('click', (e) => {
    e.stopPropagation(); // Prevent status cycle trigger
    deleteTask(task.id);
    renderBoard();
  });

  return card;
}

/**
 * Update the count badges showing how many tasks are in each status.
 * Counts reflect ALL tasks, regardless of current filter.
 */
function updateCountBadges() {
  const pendingCount = tasks.filter(t => t.status === 'pending').length;
  const inProgressCount = tasks.filter(t => t.status === 'in_progress').length;
  const completedCount = tasks.filter(t => t.status === 'completed').length;

  document.getElementById('count-pending').textContent = pendingCount;
  document.getElementById('count-in_progress').textContent = inProgressCount;
  document.getElementById('count-completed').textContent = completedCount;
}

/**
 * Show or hide the empty state message.
 * @param {boolean} show - Whether to display the empty state
 */
function toggleEmptyState(show) {
  const emptyState = document.getElementById('empty-state');
  if (show) {
    emptyState.style.display = 'block';
  } else {
    emptyState.style.display = 'none';
  }
}

// ──────────────────────────────────────────
// 5. UTILITY FUNCTIONS
// ──────────────────────────────────────────

/**
 * Escape HTML special characters to prevent XSS when injecting user input.
 * @param {string} text - Raw string from user input
 * @returns {string} Sanitized string safe for innerHTML
 */
function escapeHtml(text) {
  const div = document.createElement('div');
  div.appendChild(document.createTextNode(text));
  return div.innerHTML;
}

// ──────────────────────────────────────────
// 6. EVENT LISTENERS & APP INITIALIZATION
// ──────────────────────────────────────────

/**
 * Initialize the application: load data, bind events, render UI.
 */
function init() {
  // Load persisted tasks from localStorage
  loadTasks();

  // ── Form submission: add new task ──
  const taskForm = document.getElementById('task-form');
  taskForm.addEventListener('submit', (e) => {
    e.preventDefault();

    const titleInput = document.getElementById('task-title');
    const descInput = document.getElementById('task-desc');

    const title = titleInput.value.trim();
    const description = descInput.value.trim();

    // Basic validation
    if (!title) return;

    addTask(title, description);

    // Reset form and re-render
    taskForm.reset();
    renderBoard();
  });

  // ── Filter buttons: change current filter ──
  const filterButtons = document.querySelectorAll('.filter-btn');
  filterButtons.forEach(btn => {
    btn.addEventListener('click', () => {
      // Remove active class from all buttons
      filterButtons.forEach(b => b.classList.remove('active'));
      // Add active class to clicked button
      btn.classList.add('active');

      // Update filter and re-render
      currentFilter = btn.dataset.filter;
      renderBoard();
    });
  });

  // ── Initial render on page load ──
  renderBoard();
}

// Start the app when the DOM is fully loaded
document.addEventListener('DOMContentLoaded', init);
```

## README.md

```markdown
# 📋 Task Manager

A clean, responsive task management application built with vanilla JavaScript. No frameworks, no dependencies — just HTML, CSS, and JS.

## Features

- **Add tasks** with a title and optional description
- **Three status levels**: Pending → In Progress → Completed
- **Click to cycle** through statuses (each click advances the status)
- **Delete tasks** with the trash button
- **Grouped board view** — tasks displayed in three columns by status
- **Filter bar** — show All, Pending, In Progress, or Completed tasks
- **Persistent storage** — tasks survive page reloads via `localStorage`
- **Responsive design** — works on desktop, tablet, and mobile

## File Structure

```
├── index.html      # Application HTML structure
├── styles.css      # All styling (CSS variables, responsive breakpoints)
├── app.js          # Application logic (CRUD, rendering, localStorage)
└── README.md       # This file
```

## Setup & Running

1. **Clone or download** the project files into a folder.
2. **Open `index.html`** in any modern web browser:
   - Double-click the file, or
   - Use a local server (recommended for best practice):
     ```bash
     # Using Python
     python -m http.server 8000

     # Using Node.js
     npx serve .
     ```
   - Then navigate to `http://localhost:8000`
3. **No build step required** — the app runs directly in the browser.

## How It Works

### Data Flow
```
User Action → Event Listener → State Update → saveTasks() → localStorage
                                                        ↓
                                              renderBoard() ← UI Refresh
```

### Status Cycling
Each task card cycles through statuses on click:
```
pending ──click──> in_progress ──click──> completed ──click──> pending ...
```

### Persistence
- Tasks are stored as a JSON array under the key `task_manager_tasks` in localStorage.
- On page load, `loadTasks()` reads this data and populates the in-memory state.
- Every add/delete/cycle operation calls `saveTasks()` to sync back to storage.

## Browser Support

Works in all modern browsers:
- Chrome 90+
- Firefox 88+
- Safari 14+
- Edge 90+

## Customization Tips

| Want to... | Where to look |
|---|---|
| Change colors | `styles.css` → `:root` CSS variables |
| Add more statuses | `app.js` → `cycleTaskStatus()` + add column in HTML/CSS |
| Change storage key | `app.js` → `STORAGE_KEY` constant |
| Add due dates | Extend the task object in `addTask()` and update rendering |

## License

MIT — feel free to use this project for learning or as a starting point for your own app.
```

