## `app.js`

```javascript
/* ============================================================
   GERENCIADOR DE TAREFAS — app.js
   Aplicação completa em JavaScript puro (vanilla JS)
   ============================================================ */

// ============================================================
// 1. CONSTANTES E ESTADO DA APLICAÇÃO
// ============================================================

/** Chave usada no localStorage para persistir as tarefas */
const STORAGE_KEY = 'task_manager_tasks';

/** Lista de status válidos (ordem de exibição) */
const STATUSES = ['pendente', 'em_andamento', 'concluído'];

/** Filtro atualmente ativo */
let currentFilter = 'todas';

/** Estado central da aplicação: array de tarefas */
let tasks = [];

// ============================================================
// 2. FUNÇÕES DE PERSISTÊNCIA (localStorage)
// ============================================================

/**
 * Carrega as tarefas do localStorage.
 * Se não houver dados salvos, retorna array vazio.
 * @returns {Array} Lista de tarefas
 */
function loadTasks() {
  try {
    const data = localStorage.getItem(STORAGE_KEY);
    return data ? JSON.parse(data) : [];
  } catch (error) {
    console.error('Erro ao carregar tarefas:', error);
    return [];
  }
}

/**
 * Salva o array de tarefas no localStorage.
 * @param {Array} tasksArray - Lista de tarefas a ser salva
 */
function saveTasks(tasksArray) {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(tasksArray));
  } catch (error) {
    console.error('Erro ao salvar tarefas:', error);
  }
}

// ============================================================
// 3. FUNÇÕES DE CRIAÇÃO E MODIFICAÇÃO DE TAREFAS
// ============================================================

/**
 * Gera um ID único usando timestamp + random.
 * @returns {string} ID único
 */
function generateId() {
  return Date.now().toString(36) + Math.random().toString(36).substr(2, 5);
}

/**
 * Cria uma nova tarefa e a adiciona ao estado.
 * @param {string} title   - Título da tarefa
 * @param {string} desc    - Descrição da tarefa (opcional)
 */
function addTask(title, desc = '') {
  const newTask = {
    id: generateId(),
    title: title.trim(),
    description: desc.trim(),
    status: 'pendente', // Status padrão
    createdAt: new Date().toISOString()
  };

  tasks.push(newTask);
  saveTasks(tasks);
  renderTasks();
}

/**
 * Alterna o status da tarefa entre os três estados.
 * Ordem: pendente → em_andamento → concluído → pendente
 * @param {string} id - ID da tarefa
 */
function toggleStatus(id) {
  const task = tasks.find(t => t.id === id);
  if (!task) return;

  // Define a ordem cíclica dos status
  const order = ['pendente', 'em_andamento', 'concluído'];
  const currentIndex = order.indexOf(task.status);
  const nextIndex = (currentIndex + 1) % order.length;
  task.status = order[nextIndex];

  saveTasks(tasks);
  renderTasks();
}

/**
 * Exclui uma tarefa do estado e salva.
 * @param {string} id - ID da tarefa a ser excluída
 */
function deleteTask(id) {
  tasks = tasks.filter(t => t.id !== id);
  saveTasks(tasks);
  renderTasks();
}

// ============================================================
// 4. FUNÇÕES DE FILTRAGEM
// ============================================================

/**
 * Retorna as tarefas filtradas com base no filtro ativo.
 * @returns {Array} Tarefas filtradas
 */
function getFilteredTasks() {
  if (currentFilter === 'todas') return tasks;
  return tasks.filter(t => t.status === currentFilter);
}

/**
 * Conta quantas tarefas existem por status.
 * @returns {Object} Mapa de contagem por status
 */
function getCounts() {
  const counts = { pendente: 0, em_andamento: 0, concluído: 0 };
  tasks.forEach(t => {
    if (counts[t.status] !== undefined) counts[t.status]++;
  });
  return counts;
}

// ============================================================
// 5. FUNÇÕES DE RENDERIZAÇÃO (DOM)
// ============================================================

/**
 * Renderiza todas as seções de tarefas no DOM.
 * Atualiza listas, contadores e mensagens de vazio.
 */
function renderTasks() {
  const counts = getCounts();

  // Atualiza badges de contagem nos filtros
  document.getElementById('count-all').textContent      = tasks.length;
  document.getElementById('count-pending').textContent   = counts.pendente;
  document.getElementById('count-in-progress').textContent = counts.em_andamento;
  document.getElementById('count-completed').textContent = counts.concluído;

  // Atualiza contadores das seções
  document.getElementById('section-count-pending').textContent      = counts.pendente;
  document.getElementById('section-count-in-progress').textContent  = counts.em_andamento;
  document.getElementById('section-count-completed').textContent    = counts.concluído;

  // Renderiza cada seção de status
  STATUSES.forEach(status => {
    renderSection(status, counts[status]);
  });

  // Aplica o filtro atual às seções
  applyFilter();
}

/**
 * Renderiza uma seção específica (lista + mensagem de vazio).
 * @param {string} status   - Status da seção
 * @param {number} count    - Quantidade de tarefas no status
 */
function renderSection(status, count) {
  const listId = getStatusListId(status);
  const emptyId = getStatusEmptyId(status);
  const listEl = document.getElementById(listId);
  const emptyEl = document.getElementById(emptyId);

  // Filtra as tarefas deste status
  const sectionTasks = tasks.filter(t => t.status === status);

  // Limpa a lista existente
  listEl.innerHTML = '';

  if (sectionTasks.length === 0) {
    // Mostra mensagem de vazio, esconde a lista
    emptyEl.style.display = 'block';
    listEl.style.display = 'none';
  } else {
    // Esconde mensagem de vazio, mostra a lista
    emptyEl.style.display = 'none';
    listEl.style.display = 'flex';

    // Cria o elemento HTML para cada tarefa
    sectionTasks.forEach(task => {
      const li = createTaskElement(task);
      listEl.appendChild(li);
    });
  }
}

/**
 * Cria um elemento <li> representando uma tarefa.
 * @param {Object} task - Objeto da tarefa
 * @returns {HTMLElement} Elemento LI da tarefa
 */
function createTaskElement(task) {
  const li = document.createElement('li');
  li.className = 'task-item';
  li.dataset.status = task.status;
  li.dataset.id = task.id;

  // Formata a data de criação para exibição
  const dateStr = formatDate(task.createdAt);

  // Monta o HTML interno do card
  li.innerHTML = `
    <div class="task-checkbox"></div>
    <div class="task-content">
      <div class="task-title">${escapeHtml(task.title)}</div>
      ${task.description ? `<div class="task-desc">${escapeHtml(task.description)}</div>` : ''}
      <div class="task-meta">Criada em ${dateStr}</div>
    </div>
    <button class="btn-delete" title="Excluir tarefa" aria-label="Excluir tarefa: ${escapeHtml(task.title)}">
      🗑️
    </button>
  `;

  // Evento: clicar no card alterna o status
  li.addEventListener('click', (e) => {
    // Não alterna se o clique foi no botão de excluir
    if (e.target.closest('.btn-delete')) return;
    toggleStatus(task.id);
  });

  // Evento: clicar no botão de excluir remove a tarefa
  const deleteBtn = li.querySelector('.btn-delete');
  deleteBtn.addEventListener('click', (e) => {
    e.stopPropagation(); // Impede que o clique propague para o card
    confirmAndDelete(task.id, task.title);
  });

  return li;
}

/**
 * Aplica o filtro atual: mostra/esconde as seções conforme necessário.
 */
function applyFilter() {
  const sections = document.querySelectorAll('.task-section');

  sections.forEach(section => {
    const status = section.dataset.status;

    if (currentFilter === 'todas') {
      // Mostra todas as seções
      section.classList.remove('hidden');
    } else if (status === currentFilter) {
      // Mostra apenas a seção correspondente ao filtro
      section.classList.remove('hidden');
    } else {
      // Esconde as demais seções
      section.classList.add('hidden');
    }
  });
}

/**
 * Atualiza o estado visual dos botões de filtro.
 */
function updateFilterButtons() {
  const buttons = document.querySelectorAll('.btn-filter');
  buttons.forEach(btn => {
    const filter = btn.dataset.filter;
    if (filter === currentFilter) {
      btn.classList.add('active');
    } else {
      btn.classList.remove('active');
    }
  });
}

// ============================================================
// 6. FUNÇÕES AUXILIARES
// ============================================================

/**
 * Retorna o ID do elemento <ul> correspondente a um status.
 * @param {string} status - Status da tarefa
 * @returns {string} ID do elemento lista
 */
function getStatusListId(status) {
  const map = {
    'pendente': 'list-pending',
    'em_andamento': 'list-in-progress',
    'concluído': 'list-completed'
  };
  return map[status] || 'list-pending';
}

/**
 * Retorna o ID do elemento de mensagem vazia correspondente a um status.
 * @param {string} status - Status da tarefa
 * @returns {string} ID do elemento vazio
 */
function getStatusEmptyId(status) {
  const map = {
    'pendente': 'empty-pending',
    'em_andamento': 'empty-in-progress',
    'concluído': 'empty-completed'
  };
  return map[status] || 'empty-pending';
}

/**
 * Escapa caracteres HTML para prevenir XSS.
 * @param {string} text - Texto a ser escapado
 * @returns {string} Texto seguro para inserção no DOM
 */
function escapeHtml(text) {
  const div = document.createElement('div');
  div.textContent = text;
  return div.innerHTML;
}

/**
 * Formata uma data ISO para o formato brasileiro (DD/MM/YYYY).
 * @param {string} isoDate - Data no formato ISO 8601
 * @returns {string} Data formatada
 */
function formatDate(isoDate) {
  const date = new Date(isoDate);
  return date.toLocaleDateString('pt-BR', {
    day: '2-digit',
    month: '2-digit',
    year: 'numeric'
  });
}

/**
 * Exibe um diálogo de confirmação antes de excluir.
 * @param {string} id     - ID da tarefa
 * @param {string} title  - Título da tarefa (para mensagem)
 */
function confirmAndDelete(id, title) {
  if (confirm(`Deseja realmente excluir a tarefa "${title}"?`)) {
    deleteTask(id);
  }
}

// ============================================================
// 7. EVENT LISTENERS E INICIALIZAÇÃO
// ============================================================

/**
 * Inicializa a aplicação: carrega dados, configura eventos e renderiza.
 */
function init() {
  // Carrega tarefas salvas do localStorage
  tasks = loadTasks();

  // Configura o formulário de adição
  const form = document.getElementById('task-form');
  form.addEventListener('submit', (e) => {
    e.preventDefault();

    const titleInput = document.getElementById('task-title');
    const descInput = document.getElementById('task-desc');

    const title = titleInput.value.trim();
    const desc = descInput.value.trim();

    if (!title) return; // Validação: título é obrigatório

    addTask(title, desc);

    // Limpa os campos após adicionar
    titleInput.value = '';
    descInput.value = '';
  });

  // Configura os botões de filtro
  const filterButtons = document.querySelectorAll('.btn-filter');
  filterButtons.forEach(btn => {
    btn.addEventListener('click', () => {
      currentFilter = btn.dataset.filter;
      updateFilterButtons();
      applyFilter();
    });
  });

  // Renderiza a interface pela primeira vez
  renderTasks();
  updateFilterButtons();
}

// Inicia a aplicação quando o DOM estiver pronto
document.addEventListener('DOMContentLoaded', init);
