## `app.js`

```javascript
/**
 * =============================================
 * TASK MANAGEMENT APPLICATION
 * =============================================
 * A vanilla JavaScript app that allows users to
 * create, view, filter, toggle, and delete tasks.
 * Tasks are persisted in localStorage.
 * =============================================
 */

// ==================== STATE ====================
let tasks = [];          // Array of task objects
let currentFilter = 'all'; // Current active filter

// ==================== DOM REFERENCES ====================
const taskForm = document.getElementById('task-form');
const titleInput = document.getElementById('task-title');
const descInput = document.getElementById('task-desc');
const taskBoard = document.getElementById('task-board');
const emptyState = document.getElementById('empty-state');
const filterButtons = document.querySelectorAll('.btn-filter');

// ==================== LOCAL STORAGE ====================

/**
 * Load tasks from localStorage on app initialization.
 * Falls back to an empty array if no data exists or parsing fails.
 */
function loadTasks() {
  try {
    const stored = localStorage.getItem('taskManager_tasks');
    tasks = stored ? JSON.parse(stored) : [];
  } catch (e) {
    console.error('Failed to load tasks from localStorage:', e);
    tasks = [];
  }
}

/**
 * Save the current tasks array to localStorage.
 */
function saveTasks() {
  try {
    localStorage.setItem('taskManager_tasks', JSON.stringify(tasks));
  } catch (e) {
    console.error('Failed to save tasks to localStorage:', e);
  }
}

// ==================== TASK CREATION ====================

/**
 * Generate a unique ID for a new task.
 * Uses timestamp + random suffix to minimize collision risk.
 */
function generateId() {
  return Date.now().toString(36) + Math.random().toString(36).substr(2, 5);
}

/**
 * Format a date string for display (e.g., "Jan 15, 2025").
 */
function formatDate(timestamp) {
  const date = new Date(timestamp);
  return date.toLocaleDateString('en-US', {
    month: 'short',
    day: 'numeric',
    year: 'numeric'
  });
}

/**
 * Add a new task from the form inputs.
 * Validates that the title is not empty, then creates and saves the task.
 */
function addTask(title, description) {
  const task = {
    id: generateId(),
    title: title.trim(),
    description: description.trim(),
    status: 'pending', // default status
    createdAt: Date.now()
  };

  tasks.push(task);
  saveTasks();
  renderTasks();
}

// ==================== TASK DELETION ====================

/**
 * Remove a task by its ID.
 */
function deleteTask(id) {
  tasks = tasks.filter(task => task.id !== id);
  saveTasks();
  renderTasks();
}

// ==================== TASK TOGGLE (STATUS CYCLE) ====================

/**
 * Cycle a task's status: pending → in_progress → completed → pending.
 */
function toggleTask(id) {
  const task = tasks.find(t => t.id === id);
  if (!task) return;

  // Define the status cycle order
  const statusOrder = ['pending', 'in_progress', 'completed'];
  const currentIndex = statusOrder.indexOf(task.status);
  const nextIndex = (currentIndex + 1) % statusOrder.length;

  task.status = statusOrder[nextIndex];
  saveTasks();
  renderTasks();
}

// ==================== FILTERING ====================

/**
 * Set the active filter and re-render.
 */
function setFilter(filter) {
  currentFilter = filter;

  // Update button states
  filterButtons.forEach(btn => {
    const isActive = btn.dataset.filter === filter;
    btn.classList.toggle('active', isActive);
    btn.setAttribute('aria-pressed', isActive);
  });

  renderTasks();
}

/**
 * Return tasks filtered by the current filter setting.
 */
function getFilteredTasks() {
  if (currentFilter === 'all') return tasks;
  return tasks.filter(task => task.status === currentFilter);
}

// ==================== RENDERING ====================

/**
 * Create the HTML for a single task card.
 */
function createTaskCard(task) {
  const card = document.createElement('div');
  card.className = 'task-card';
  card.dataset.status = task.status;
  card.dataset.id = task.id;

  // Clicking the card toggles its status
  card.addEventListener('click', (e) => {
    // Don't toggle if the delete button was clicked
    if (!e.target.closest('.btn-delete')) {
      toggleTask(task.id);
    }
  });

  card.innerHTML = `
    <button
      class="btn-delete"
      title="Delete task"
      aria-label="Delete ${task.title}"
    >✕</button>
    <div class="task-title">${escapeHtml(task.title)}</div>
    ${task.description ? `<div class="task-desc">${escapeHtml(task.description)}</div>` : ''}
    <div class="task-meta">
      <span class="status-badge ${task.status}">${formatStatus(task.status)}</span>
      <span class="task-date">${formatDate(task.createdAt)}</span>
    </div>
  `;

  // Attach delete handler
  const deleteBtn = card.querySelector('.btn-delete');
  deleteBtn.addEventListener('click', (e) => {
    e.stopPropagation(); // Prevent toggling when deleting
    deleteTask(task.id);
  });

  return card;
}

/**
 * Format a status string for display.
 */
function formatStatus(status) {
  const labels = {
    pending: 'Pending',
    in_progress: 'In Progress',
    completed: 'Completed'
  };
  return labels[status] || status;
}

/**
 * Escape HTML to prevent XSS when rendering user input.
 */
function escapeHtml(text) {
  const div = document.createElement('div');
  div.textContent = text;
  return div.innerHTML;
}

/**
 * Update the count badges for each column.
 */
function updateCounts() {
  const counts = { pending: 0, in_progress: 0, completed: 0 };
  tasks.forEach(task => counts[task.status]++);

  document.getElementById('count-pending').textContent = counts.pending;
  document.getElementById('count-in_progress').textContent = counts.in_progress;
  document.getElementById('count-completed').textContent = counts.completed;
}

/**
 * Main render function: clears and rebuilds all task lists.
 */
function renderTasks() {
  // Clear existing task cards from each column
  ['pending', 'in_progress', 'completed'].forEach(status => {
    const list = document.getElementById(`list-${status}`);
    list.innerHTML = '';
  });

  // Group tasks by status for the board view
  const groupedTasks = { pending: [], in_progress: [], completed: [] };
  tasks.forEach(task => {
    if (groupedTasks[task.status]) {
      groupedTasks[task.status].push(task);
    }
  });

  // Render cards into each column
  Object.entries(groupedTasks).forEach(([status, statusTasks]) => {
    const list = document.getElementById(`list-${status}`);
    statusTasks.forEach(task => {
      list.appendChild(createTaskCard(task));
    });
  });

  // Update count badges
  updateCounts();

  // Show/hide empty state based on filtered results
  const filtered = getFilteredTasks();
  if (filtered.length === 0) {
    emptyState.classList.remove('hidden');
    taskBoard.classList.add('hidden');
  } else {
    emptyState.classList.add('hidden');
    taskBoard.classList.remove('hidden');
  }
}

// ==================== EVENT LISTENERS ====================

/**
 * Handle form submission to add a new task.
 */
taskForm.addEventListener('submit', (e) => {
  e.preventDefault();

  const title = titleInput.value.trim();
  const description = descInput.value.trim();

  if (!title) return; // HTML5 validation handles this, but be safe

  addTask(title, description);

  // Reset form
  titleInput.value = '';
  descInput.value = '';
  titleInput.focus();
});

/**
 * Handle filter button clicks.
 */
filterButtons.forEach(btn => {
  btn.addEventListener('click', () => {
    setFilter(btn.dataset.filter);
  });
});

// ==================== INITIALIZATION ====================

/**
 * Load saved tasks and render the initial view on page load.
 */
function init() {
  loadTasks();
  renderTasks();
}

init();
```

