  gap: 1rem;
  margin-bottom: 1.5rem;
}

.board {
  background: var(--color-surface);
  border-radius: var(--radius);
  padding: 1rem;
  box-shadow: var(--shadow);
  min-height: 200px;
  transition: box-shadow 0.2s;
}

.board:hover {
  box-shadow: var(--shadow-md);
}

.column-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 1rem;
  padding-bottom: 0.75rem;
  border-bottom: 2px solid var(--color-border);
}

/* Badges de status nas colunas */
.status-badge {
  font-size: 0.85rem;
  font-weight: 700;
  padding: 0.3rem 0.75rem;
  border-radius: 50px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.badge-pendente {
  background-color: var(--pendente-bg);
  color: var(--pendente-text);
  border: 1px solid var(--pendente-border);
}

.badge-em_andamento {
  background-color: var(--em_andamento-bg);
  color: var(--em_andamento-text);
  border: 1px solid var(--em_andamento-border);
}

.badge-concluído {
  background-color: var(--concluído-bg);
  color: var(--concluído-text);
  border: 1px solid var(--concluído-border);
}

.count-badge {
  background: var(--color-bg);
  color: var(--color-text-light);
  font-size: 0.8rem;
  font-weight: 700;
  padding: 0.2rem 0.6rem;
  border-radius: 50px;
  min-width: 28px;
  text-align: center;
}

.task-list {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  min-height: 100px;
}

/* =============================================
   CARD DE TAREFA
   ============================================= */
.task-card {
  background: var(--color-surface);
  border: 2px solid var(--color-border);
  border-radius: 10px;
  padding: 1rem;
  cursor: pointer;
  transition: all 0.2s;
  position: relative;
}

.task-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-1px);
}

/* Borda colorida conforme o status */
.task-card[data-status="pendente"] {
  border-left: 4px solid var(--pendente-border);
}

.task-card[data-status="em_andamento"] {
  border-left: 4px solid var(--em_andamento-border);
}

.task-card[data-status="concluído"] {
  border-left: 4px solid var(--concluído-border);
  opacity: 0.8;
}

/* Tarefa concluída — texto riscado */
.task-card.concluído .task-title {
  text-decoration: line-through;
  color: var(--color-text-light);
}

.task-title {
  font-size: 1rem;
  font-weight: 600;
  color: var(--color-text);
  margin-bottom: 0.35rem;
  word-break: break-word;
}

.task-desc {
  font-size: 0.875rem;
  color: var(--color-text-light);
  margin-bottom: 0.75rem;
  word-break: break-word;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.task-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
}

.task-date {
  font-size: 0.75rem;
  color: var(--color-text-light);
}

.task-actions {
  display: flex;
  gap: 0.35rem;
  opacity: 0;
  transition: opacity 0.2s;
}

.task-card:hover .task-actions {
  opacity: 1;
}

/* Botões de ação do card */
.btn-icon {
  width: 32px;
  height: 32px;
  border: none;
  border-radius: 6px;
  cursor: pointer;
  font-size: 0.85rem;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background-color 0.2s, transform 0.1s;
}

.btn-icon:active {
  transform: scale(0.9);
}

.btn-edit {
  background: #eff6ff;
  color: #3b82f6;
}

.btn-edit:hover {
  background: #dbeafe;
}

.btn-delete {
  background: #fef2f2;
  color: #ef4444;
}

.btn-delete:hover {
  background: #fee2e2;
}

/* =============================================
   ESTADO VAZIO
