## `app.js`

```javascript
/**
 * =============================================
 * GERENCIADOR DE TAREFAS — app.js
 * Aplicação completa em JavaScript puro (vanilla)
 * =============================================
 */

// =============================================
// 1. CONSTANTES E ESTADO DA APLICAÇÃO
// =============================================

/** Chave usada no localStorage para persistir as tarefas */
const STORAGE_KEY = 'task_manager_tasks';

/** Lista de status válidos para uma tarefa */
const STATUSES = ['pendente', 'em_andamento', 'concluído'];

/** Filtro atualmente ativo (começa com "todas") */
let currentFilter = 'todas';

/** Array principal de tarefas em memória */
let tasks = [];

// =============================================
// 2. FUNÇÕES DE PERSISTÊNCIA (localStorage)
// =============================================

/**
 * Carrega as tarefas do localStorage para a memória.
 * Se não houver dados salvos, inicia com array vazio.
 */
function loadTasks() {
  try {
    const stored = localStorage.getItem(STORAGE_KEY);
    tasks = stored ? JSON.parse(stored) : [];
  } catch (e) {
    console.error('Erro ao carregar tarefas do localStorage:', e);
    tasks = [];
  }
}

/**
 * Salva o array de tarefas no localStorage.
 * Converte o array para string JSON antes de armazenar.
 */
function saveTasks() {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(tasks));
  } catch (e) {
    console.error('Erro ao salvar tarefas no localStorage:', e);
  }
}

// =============================================
// 3. FUNÇÕES DE CRIAÇÃO E EDIÇÃO
// =============================================

/**
 * Cria um novo objeto de tarefa com ID único e data de criação.
 * @param {string} title - Título da tarefa
 * @param {string} description - Descrição da tarefa
 * @returns {object} A nova tarefa
 */
function createTask(title, description) {
  return {
    id: generateId(),
    title: title.trim(),
    description: description.trim(),
    status: 'pendente',
    createdAt: new Date().toISOString()
  };
}

/**
 * Gera um ID único usando timestamp + random.
 * @returns {string} ID único
 */
function generateId() {
  return Date.now().toString(36) + Math.random().toString(36).substr(2, 5);
}

/**
 * Adiciona uma nova tarefa ao array e salva no localStorage.
 * @param {string} title - Título
 * @param {string} description - Descrição
 */
function addTask(title, description) {
  const task = createTask(title, description);
  tasks.push(task);
  saveTasks();
  renderAll();
}

/**
 * Alterna o status da tarefa entre os três estados possíveis.
 * Ordem: pendente → em_andamento → concluído → pendente
 * @param {string} id - ID da tarefa
 */
function toggleTaskStatus(id) {
  const task = tasks.find(t => t.id === id);
  if (!task) return;

  // Avança para o próximo status
  const currentIndex = STATUSES.indexOf(task.status);
  task.status = STATUSES[(currentIndex + 1) % STATUSES.length];

  saveTasks();
  renderAll();
}

/**
 * Exclui uma tarefa do array e salva no localStorage.
 * @param {string} id - ID da tarefa
 */
function deleteTask(id) {
  tasks = tasks.filter(t => t.id !== id);
  saveTasks();
  renderAll();
}

/**
 * Abre o modal de edição preenchido com os dados da tarefa.
 * @param {string} id - ID da tarefa a ser editada
 */
function openEditModal(id) {
  const task = tasks.find(t => t.id === id);
  if (!task) return;

  document.getElementById('edit-id').value = task.id;
  document.getElementById('edit-title').value = task.title;
  document.getElementById('edit-desc').value = task.description;
  document.getElementById('edit-status').value = task.status;

  document.getElementById('modal-overlay').style.display = 'flex';
}

/**
 * Fecha o modal de edição.
 */
function closeEditModal() {
  document.getElementById('modal-overlay').style.display = 'none';
}

/**
 * Salva as alterações feitas no modal de edição.
 * @param {string} id - ID da tarefa
 * @param {string} title - Novo título
 * @param {string} description - Nova descrição
 * @param {string} status - Novo status
 */
function saveEditTask(id, title, description, status) {
  const task = tasks.find(t => t.id === id);
  if (!task) return;

  task.title = title.trim();
  task.description = description.trim();
  task.status = status;

  saveTasks();
  closeEditModal();
  renderAll();
}

// =============================================
// 4. FUNÇÕES DE FILTRAGEM
// =============================================

/**
 * Retorna as tarefas filtradas com base no filtro atual.
 * @returns {Array} Tarefas filtradas
 */
function getFilteredTasks() {
  if (currentFilter === 'todas') {
    return tasks;
  }
  return tasks.filter(t => t.status === currentFilter);
}

/**
 * Alterna o filtro ativo e re-renderiza a interface.
 * @param {string} filter - Novo filtro ('todas', 'pendente', 'em_andamento', 'concluído')
 */
function setFilter(filter) {
  currentFilter = filter;

  // Atualiza o estado visual dos botões de filtro
  document.querySelectorAll('.filter-btn').forEach(btn => {
    btn.classList.toggle('active', btn.dataset.filter === filter);
  });

  renderAll();
}

// =============================================
// 5. FUNÇÕES DE RENDERIZAÇÃO (UI)
// =============================================

/**
 * Formata uma data ISO para exibição em português.
 * @param {string} isoDate - Data no formato ISO
 * @returns {string} Data formatada
 */
function formatDate(isoDate) {
  const date = new Date(isoDate);
  return date.toLocaleDateString('pt-BR', {
    day: '2-digit',
    month: '2-digit',
    year: 'numeric'
  });
}

/**
 * Cria o HTML de um card de tarefa.
 * @param {object} task - Objeto da tarefa
 * @returns {string} HTML do card
 */
function renderTaskCard(task) {
  // Ícone conforme o status atual
  const statusIcon = {
    'pendente': '⏳',
    'em_andamento': '🔄',
    'concluído': '✅'
  };

  return `
    <div class="task-card ${task.status === 'concluído' ? 'concluído' : ''}"
         data-status="${task.status}"
         data-id="${task.id}"
         title="Clique para alterar o status">
      <div class="task-title">${escapeHtml(task.title)}</div>
      ${task.description
        ? `<div class="task-desc">${escapeHtml(task.description)}</div>`
        : ''}
      <div class="task-meta">
        <span class="task-date">
          ${statusIcon[task.status]} ${formatDate(task.createdAt)}
        </span>
        <div class="task-actions">
          <button class="btn-icon btn-edit"
                  onclick="openEditModal('${task.id}')"
                  title="Editar tarefa">
            ✏️
          </button>
          <button class="btn-icon btn-delete"
                  onclick="deleteTask('${task.id}')"
                  title="Excluir tarefa">
            🗑️
          </button>
        </div>
      </div>
    </div>
  `;
}

/**
 * Escapa caracteres HTML para prevenir XSS.
 * @param {string} text - Texto cru
 * @returns {string} Texto seguro
 */
function escapeHtml(text) {
  const div = document.createElement('div');
  div.textContent = text;
  return div.innerHTML;
}

/**
 * Renderiza todas as colunas (boards) com as tarefas correspondentes.
 * Considera o filtro ativo para decidir quais tarefas exibir.
 */
function renderBoards() {
  const filteredTasks = getFilteredTasks();

  STATUSES.forEach(status => {
    const listEl = document.getElementById(`list-${status}`);
    const countEl = document.getElementById(`count-${status}`);

    // Filtra as tarefas deste status (respeitando o filtro global)
    let statusTasks = tasks.filter(t => t.status === status);

    // Se o filtro for diferente de "todas", só mostra a coluna do filtro
    if (currentFilter !== 'todas' && currentFilter !== status) {
      statusTasks = [];
    }

    // Atualiza o contador da coluna
    countEl.textContent = statusTasks.length;

    // Renderiza os cards ou mensagem vazia
    if (statusTasks.length === 0) {
      listEl.innerHTML = `
        <div class="empty-column" style="text-align:center; padding:1.5rem; color:var(--color-text-light); font-size:0.875rem;">
          Nenhuma tarefa
        </div>
      `;
    } else {
      listEl.innerHTML = statusTasks.map(renderTaskCard).join('');
    }
  });

  // Atualiza o contador geral de tarefas
  const total = tasks.length;
  document.getElementById('task-count').textContent =
    `${total} tarefa${total !== 1 ? 's' : ''} no total`;

  // Mostra/oculta a mensagem de estado vazio global
  const emptyState = document.getElementById('empty-state');
  emptyState.style.display = tasks.length === 0 ? 'block' : 'none';
}

/**
 * Renderiza toda a interface a partir do estado atual.
 */
function renderAll() {
  renderBoards();
}

// =============================================
// 6. EVENT LISTENERS (Event Delegation)
// =============================================

/**
 * Configura todos os event listeners da aplicação.
 * Usa event delegation para lidar com cliques nos cards dinâmicos.
 */
function setupEventListeners() {

  // --- Formulário de adição de tarefas ---
  document.getElementById('task-form').addEventListener('submit', (e) => {
    e.preventDefault();

    const titleInput = document.getElementById('task-title');
    const descInput = document.getElementById('task-desc');

    const title = titleInput.value.trim();
    const description = descInput.value.trim();

    if (!title) return; // Validação já feita pelo atributo "required" do HTML

    addTask(title, description);

    // Limpa o formulário após adicionar
    titleInput.value = '';
    descInput.value = '';
  });

  // --- Cliques nos cards (event delegation para toggle de status) ---
  document.getElementById('boards-container').addEventListener('click', (e) => {
    const card = e.target.closest('.task-card');

    // Se clicou em um botão de ação, não alterna o status
    if (e.target.closest('.btn-edit') || e.target.closest('.btn-delete')) {
      return;
    }

    if (card) {
      const id = card.dataset.id;
      toggleTaskStatus(id);
    }
  });

  // --- Botões de filtro ---
  document.getElementById('filter-buttons').addEventListener('click', (e) => {
    const btn = e.target.closest('.filter-btn');
    if (btn) {
      setFilter(btn.dataset.filter);
    }
  });

  // --- Formulário de edição no modal ---
  document.getElementById('edit-form').addEventListener('submit', (e) => {
    e.preventDefault();

    const id = document.getElementById('edit-id').value;
    const title = document.getElementById('edit-title').value;
    const description = document.getElementById('edit-desc').value;
    const status = document.getElementById('edit-status').value;

    if (!title.trim()) return;

    saveEditTask(id, title, description, status);
  });

  // --- Botão fechar modal ---
  document.getElementById('btn-close-modal').addEventListener('click', closeEditModal);

  // --- Fechar modal clicando fora dele (no overlay) ---
  document.getElementById('modal-overlay').addEventListener('click', (e) => {
    if (e.target === e.currentTarget) {
      closeEditModal();
    }
  });

  // --- Fechar modal com tecla ESC ---
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') {
      closeEditModal();
    }
  });
}

// =============================================
// 7. INICIALIZAÇÃO DA APLICAÇÃO
// =============================================

/**
 * Função chamada quando o DOM está pronto.
 * Carrega os dados, configura eventos e renderiza a interface.
 */
function init() {
  loadTasks();       // Recupera tarefas do localStorage
  setupEventListeners(); // Configura todos os event listeners
  renderAll();        // Renderiza a interface inicial
}

// Inicia a aplicação assim que o HTML for carregado
document.addEventListener('DOMContentLoaded', init);
```

