## app.js

```javascript
/**
 * =============================================
 * TASK MANAGEMENT APPLICATION
 * =============================================
 * A vanilla JavaScript task manager with:
 *   - Add / delete / toggle tasks
 *   - Grouped display by status (Pending, In Progress, Completed)
 *   - Filter bar to show specific statuses
 *   - localStorage persistence across sessions
 * =============================================
 */

// ==================== STATE MANAGEMENT ====================

/**
 * Application state object.
 * Holds the current list of tasks and the active filter.
 */
const state = {
  tasks: [],       // Array of task objects loaded from localStorage
  filter: 'all',   // Current filter: 'all' | 'pending' | 'in_progress' | 'completed'
};

// ==================== LOCAL STORAGE HELPERS ====================

/**
 * Key used in localStorage for persisting tasks.
 */
const STORAGE_KEY = 'task_manager_tasks';

/**
 * Load tasks from localStorage.
 * Returns an empty array if no data is found or if the stored value is invalid JSON.
 */
function loadTasks() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    return raw ? JSON.parse(raw) : [];
  } catch (e) {
    console.warn('Failed to load tasks from localStorage:', e);
    return [];
  }
}

/**
 * Save the current tasks array to localStorage.
 */
function saveTasks() {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(state.tasks));
  } catch (e) {
    console.warn('Failed to save tasks to localStorage:', e);
  }
}

// ==================== TASK CRUD OPERATIONS ====================

/**
 * Generate a unique ID for a new task.
 * Uses a combination of timestamp and random string.
 */
function generateId() {
  return Date.now().toString(36) + Math.random().toString(36).substr(2, 5);
}

/**
 * Format a date into a human-readable string (e.g., "Jan 15, 2024").
 */
function formatDate(timestamp) {
  const date = new Date(timestamp);
  return date.toLocaleDateString('en-US', {
    month: 'short',
    day: 'numeric',
    year: 'numeric',
  });
}

/**
 * Add a new task to the state.
 * @param {string} title - The task title (required).
 * @param {string} description - The task description (optional).
 */
function addTask(title, description) {
  const task = {
    id: generateId(),
    title: title.trim(),
    description: description.trim(),
    status: 'pending', // Default status
    createdAt: Date.now(),
  };

  state.tasks.push(task);
  saveTasks();
}

/**
 * Delete a task by its ID.
 * @param {string} taskId - The unique ID of the task to delete.
 */
function deleteTask(taskId) {
  state.tasks = state.tasks.filter((task) => task.id !== taskId);
  saveTasks();
}

/**
 * Toggle a task's status in a cycle: pending → in_progress → completed → pending.
 * @param {string} taskId - The unique ID of the task to toggle.
 */
function toggleTask(taskId) {
  const task = state.tasks.find((t) => t.id === taskId);
  if (!task) return;

  // Cycle through statuses
  const statusOrder = ['pending', 'in_progress', 'completed'];
  const currentIndex = statusOrder.indexOf(task.status);
  task.status = statusOrder[(currentIndex + 1) % statusOrder.length];

  saveTasks();
}

// ==================== RENDERING ====================

/**
 * Create the HTML markup for a single task card.
 * @param {Object} task - The task object.
 * @returns {string} HTML string for the task card.
 */
function createTaskCard(task) {
  const statusLabels = {
    pending: 'Pending',
    in_progress: 'In Progress',
    completed: 'Completed',
  };

  return `
    <div class="task-card" data-id="${task.id}" data-status="${task.status}">
      <button
        class="btn-delete"
        title="Delete task"
        aria-label="Delete ${task.title}"
      >✕</button>
      <div class="task-title">${escapeHtml(task.title)}</div>
      ${task.description ? `<div class="task-desc">${escapeHtml(task.description)}</div>` : ''}
      <div class="task-meta">
        <span class="task-date">${formatDate(task.createdAt)}</span>
        <span class="status-badge ${task.status}">${statusLabels[task.status]}</span>
      </div>
    </div>
  `;
}

/**
 * Escape HTML special characters to prevent XSS.
 * @param {string} text - Raw string input.
 * @returns {string} Sanitized string safe for innerHTML.
 */
function escapeHtml(text) {
  const div = document.createElement('div');
  div.appendChild(document.createTextNode(text));
  return div.innerHTML;
}

/**
 * Render all task columns based on the current filter and state.
 * Updates both the task cards and the column counts.
 */
function renderTasks() {
  // Determine which statuses to display
  const statuses = state.filter === 'all'
    ? ['pending', 'in_progress', 'completed']
    : [state.filter];

  let totalVisible = 0;

  statuses.forEach((status) => {
    // Filter tasks for this status
    const filteredTasks = state.tasks.filter(
      (task) => task.status === status
    );

    // Update the count badge
    const countEl = document.getElementById(`count-${status}`);
    if (countEl) {
      countEl.textContent = filteredTasks.length;
    }

    // Render task cards into the correct column
    const listEl = document.getElementById(`list-${status}`);
    if (listEl) {
      if (filteredTasks.length === 0) {
        listEl.innerHTML = `<p style="color: var(--color-text-muted); font-size: 0.85rem; text-align: center; padding: 1rem;">No tasks</p>`;
      } else {
        listEl.innerHTML = filteredTasks.map(createTaskCard).join('');
        totalVisible += filteredTasks.length;
      }
    }
  });

  // Show/hide empty state message
  const emptyState = document.getElementById('empty-state');
  if (state.tasks.length === 0) {
    emptyState.style.display = 'block';
  } else {
    emptyState.style.display = totalVisible === 0 ? 'block' : 'none';
  }
}

// ==================== EVENT HANDLERS ====================

/**
 * Handle the "Add Task" form submission.
 * Prevents default form behavior, reads inputs, adds the task, and resets the form.
 */
function handleFormSubmit(e) {
  e.preventDefault();

  const titleInput = document.getElementById('task-title');
  const descInput = document.getElementById('task-desc');

  const title = titleInput.value.trim();
  const description = descInput.value.trim();

  if (!title) return; // Should be caught by HTML required attribute, but safety first

  addTask(title, description);

  // Reset form and re-render
  titleInput.value = '';
  descInput.value = '';
  renderTasks();
}

/**
 * Handle clicks on the task board (event delegation).
 * Determines whether a click was on a delete button or the card itself.
 */
function handleBoardClick(e) {
  const board = document.getElementById('task-board');
  if (!board.contains(e.target)) return;

  // Find the closest task card
  const card = e.target.closest('.task-card');
  if (!card) return;

  const taskId = card.dataset.id;

  // Check if the delete button was clicked
  if (e.target.classList.contains('btn-delete')) {
    e.stopPropagation(); // Prevent toggling when deleting
    deleteTask(taskId);
    renderTasks();
    return;
  }

  // Otherwise, toggle the task status
  toggleTask(taskId);
  renderTasks();
}

/**
 * Handle clicks on filter buttons.
 * Updates the active filter and re-renders the board.
 */
function handleFilterClick(e) {
  const btn = e.target.closest('.btn-filter');
  if (!btn) return;

  const filterValue = btn.dataset.filter;
  if (!filterValue) return;

  // Update state
  state.filter = filterValue;

  // Update active button styling
  document.querySelectorAll('.btn-filter').forEach((button) => {
    button.classList.toggle('active', button === btn);
  });

  renderTasks();
}

// ==================== INITIALIZATION ====================

/**
 * Initialize the application:
 *   1. Load tasks from localStorage
 *   2. Attach event listeners
 *   3. Perform initial render
 */
function init() {
  // Load persisted tasks
  state.tasks = loadTasks();

  // Bind form submission handler
  const form = document.getElementById('task-form');
  form.addEventListener('submit', handleFormSubmit);

  // Bind task board click handler (event delegation)
  const board = document.getElementById('task-board');
  board.addEventListener('click', handleBoardClick);

  // Bind filter button clicks
  const filterSection = document.querySelector('.filter-section');
  filterSection.addEventListener('click', handleFilterClick);

  // Initial render
  renderTasks();
}

// Start the app when the DOM is fully loaded
document.addEventListener('DOMContentLoaded', init);
```

## README.md

```markdown
# Task Manager Application

A clean, responsive task management app built with vanilla JavaScript — no frameworks required.

## Features

- **Add tasks** with a title and optional description
- **Three status columns**: Pending, In Progress, Completed
- **Click to cycle** through statuses (pending → in progress → completed)
- **Filter bar** to show all, pending, in-progress, or completed tasks only
- **Delete tasks** by clicking the ✕ button on any card
- **Persistent storage** using localStorage — tasks survive page reloads
- **Responsive design** — works on desktop, tablet, and mobile

## File Structure

```
├── index.html    # HTML structure
├── styles.css    # All styling (CSS custom properties, responsive grid)
├── app.js        # Application logic (CRUD, rendering, events, localStorage)
└── README.md     # This file
```

## Setup & Running

1. **Clone or download** the three files (`index.html`, `styles.css`, `app.js`) into a folder.
2. **Open `index.html`** in any modern web browser (Chrome, Firefox, Safari, Edge).
3. That's it — no build step, no dependencies, no server required.

### Optional: Local Development Server

If you'd like to serve the files via HTTP (e.g., for testing with a live reload tool):

```bash
# Using Python 3
python -m http.server 8000

# Or using Node.js (npx)
npx serve .
```

Then open `http://localhost:8000` in your browser.

## How It Works

### Data Model

Each task is a plain JavaScript object:

```js
{
  id: "m5k3x9a1b2",       // Unique ID (timestamp + random)
  title: "Buy groceries",  // Task title
  description: "...",      // Optional description
  status: "pending",       // 'pending' | 'in_progress' | 'completed'
  createdAt: 1705312800000 // Unix timestamp in ms
}
```

### Status Cycling

Clicking a task card cycles its status in order:

> **Pending** → **In Progress** → **Completed** → **Pending** → ...

A completed task is visually indicated with a green border, strikethrough title, and "Completed" badge.

### Persistence

All tasks are serialized to JSON and stored under the key `task_manager_tasks` in the browser's localStorage. On page load, the app reads this value and restores all tasks automatically.

## Browser Support

Works in all modern browsers that support:
- ES6+ (arrow functions, template literals, `const`/`let`)
- CSS Grid
- CSS Custom Properties (variables)

## Customization Tips

| Want to change... | Edit this... |
|---|---|
| Colors / theme | `styles.css` → `:root` variables |
| Status cycle order | `app.js` → `toggleTask()` function |
| Storage key name | `app.js` → `STORAGE_KEY` constant |
| Column layout (e.g., 2 columns) | `styles.css` → `.task-board` grid-template-columns |
```

