## `app.js`

```javascript
/* =============================================
   GERENCIADOR DE TAREFAS — app.js
   Aplicação completa em JavaScript puro (vanilla)
   com persistência via localStorage.
   ============================================= */

// ==================== CONSTANTES E CONFIGURAÇÃO ====================

/** Chave usada no localStorage para salvar as tarefas */
const STORAGE_KEY = 'task_manager_tasks';

/** Opções de status disponíveis */
const STATUSES = {
  PENDENTE: 'pendente',
  EM_ANDAMENTO: 'em_andamento',
  CONCLUÍDO: 'concluído',
};

/** Textos exibidos para cada status na interface */
const STATUS_LABELS = {
  [STATUSES.PENDENTE]: '⏳ Pendentes',
  [STATUSES.EM_ANDAMENTO]: '🔄 Em Andamento',
  [STATUSES.CONCLUÍDO]: '✅ Concluídos',
};

/** Ordem de exibição das seções */
const STATUS_ORDER = [STATUSES.PENDENTE, STATUSES.EM_ANDAMENTO, STATUSES.CONCLUÍDO];

// ==================== ESTADO DA APLICAÇÃO ====================

/** Array de tarefas carregado do localStorage ou vazio */
let tasks = loadTasks();

/** Filtro atual aplicado (padrão: todas) */
let currentFilter = 'todas';

// ==================== FUNÇÕES DE PERSISTÊNCIA (localStorage) ====================

/**
 * Carrega as tarefas salvas no localStorage.
 * Se não houver dados ou se estiverem corrompidos, retorna array vazio.
 * @returns {Array} Lista de tarefas
 */
function loadTasks() {
  try {
    const data = localStorage.getItem(STORAGE_KEY);
    return data ? JSON.parse(data) : [];
  } catch (error) {
    console.error('Erro ao carregar tarefas do localStorage:', error);
    return [];
  }
}

/**
 * Salva o array de tarefas atual no localStorage.
 */
function saveTasks() {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(tasks));
  } catch (error) {
    console.error('Erro ao salvar tarefas no localStorage:', error);
  }
}

// ==================== FUNÇÕES DE GERAÇÃO DE ID ====================

/**
 * Gera um identificador único usando timestamp + random.
 * @returns {string} ID único
 */
function generateId() {
  return Date.now().toString(36) + Math.random().toString(36).substr(2, 5);
}

// ==================== FUNÇÕES DE CRIAÇÃO ====================

/**
 * Cria uma nova tarefa a partir dos dados do formulário.
 * @param {string} title   - Título da tarefa
 * @param {string} desc    - Descrição da tarefa (opcional)
 * @returns {Object} Tarefa criada
 */
function createTask(title, desc = '') {
  const task = {
    id: generateId(),
    title: title.trim(),
    description: desc.trim(),
    status: STATUSES.PENDENTE, // Padrão: pendente
    createdAt: new Date().toISOString(),
  };
  tasks.push(task);
  saveTasks();
  return task;
}

// ==================== FUNÇÕES DE ATUALIZAÇÃO ====================

/**
 * Alterna o status da tarefa ciclando entre os três estados:
 * pendente → em_andamento → concluído → pendente
 * @param {string} id - ID da tarefa
 */
function toggleTaskStatus(id) {
  const task = tasks.find((t) => t.id === id);
  if (!task) return;

  // Ciclo de status: pendente → em_andamento → concluído → pendente
  const cycle = [STATUSES.PENDENTE, STATUSES.EM_ANDAMENTO, STATUSES.CONCLUÍDO];
  const currentIndex = cycle.indexOf(task.status);
  task.status = cycle[(currentIndex + 1) % cycle.length];

  saveTasks();
  renderTasks();
}

/**
 * Exclui uma tarefa pelo ID.
 * @param {string} id - ID da tarefa a ser excluída
 */
function deleteTask(id) {
  tasks = tasks.filter((t) => t.id !== id);
  saveTasks();
  renderTasks();
  showToast('Tarefa excluída!');
}

/**
 * Remove todas as tarefas concluídas de uma vez.
 */
function clearCompletedTasks() {
  const before = tasks.length;
  tasks = tasks.filter((t) => t.status !== STATUSES.CONCLUÍDO);
  const removed = before - tasks.length;
  if (removed > 0) {
    saveTasks();
    renderTasks();
    showToast(`${removed} tarefa(s) concluída(s) removida(s)!`);
  }
}

// ==================== FUNÇÕES DE FILTRAGEM ====================

/**
 * Retorna as tarefas filtradas com base no filtro atual.
 * @returns {Array} Tarefas filtradas
 */
function getFilteredTasks() {
  if (currentFilter === 'todas') return tasks;
  return tasks.filter((t) => t.status === currentFilter);
}

// ==================== FUNÇÕES DE RENDERIZAÇÃO ====================

/**
 * Renderiza todas as tarefas na interface, agrupadas por status.
 * Se o filtro estiver ativo, mostra apenas as tarefas correspondentes.
 */
function renderTasks() {
  const container = document.getElementById('tasks-container');
  const emptyState = document.getElementById('empty-state');
  const taskCount = document.getElementById('task-count');
  const clearBtn = document.getElementById('clear-completed');

  // Limpa o container
  container.innerHTML = '';

  // Determina quais status exibir com base no filtro
  let statusesToShow;
  if (currentFilter === 'todas') {
    statusesToShow = STATUS_ORDER;
  } else {
    statusesToShow = [currentFilter];
  }

  // Conta tarefas por status para o badge
  const counts = {};
  STATUS_ORDER.forEach((s) => {
    counts[s] = tasks.filter((t) => t.status === s).length;
  });

  let totalVisible = 0;
  let hasAnyTasks = tasks.length > 0;

  // Cria uma seção para cada status
  statusesToShow.forEach((status) => {
    const statusTasks = tasks.filter((t) => t.status === status);

    // Se o filtro é "todas", esconde seções vazias
    if (currentFilter === 'todas' && statusTasks.length === 0) return;

    totalVisible += statusTasks.length;

    const section = document.createElement('section');
    section.className = `status-section status-${status}`;

    // Cabeçalho da seção com título e contagem
    section.innerHTML = `
      <div class="status-header">
        <span>${STATUS_LABELS[status]}</span>
        <span class="count">${statusTasks.length}</span>
      </div>
      <div class="task-list" id="list-${status}"></div>
    `;

    // Adiciona cada tarefa como um card
    const list = section.querySelector('.task-list');
    statusTasks.forEach((task) => {
      list.appendChild(createTaskCard(task));
    });

    container.appendChild(section);
  });

  // Atualiza o contador de tarefas
  taskCount.textContent = `${tasks.length} tarefa(s) no total`;

  // Mostra/esconde botão de limpar concluídos
  if (counts[STATUSES.CONCLUÍDO] > 0) {
    clearBtn.classList.remove('hidden');
  } else {
    clearBtn.classList.add('hidden');
  }

  // Mostra/esconde estado vazio
  if (!hasAnyTasks) {
    emptyState.classList.remove('hidden');
  } else {
    emptyState.classList.add('hidden');
  }
}

/**
 * Cria um elemento DOM representando um cartão de tarefa.
 * @param {Object} task - Objeto da tarefa
 * @returns {HTMLElement} Card da tarefa
 */
function createTaskCard(task) {
  const card = document.createElement('div');
  card.className = `task-card status-${task.status}`;
  card.dataset.id = task.id;

  // Formata a data de criação
  const date = new Date(task.createdAt);
  const formattedDate = date.toLocaleDateString('pt-BR', {
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
  });

  card.innerHTML = `
    <div class="task-checkbox"></div>
    <div class="task-content">
      <div class="task-title">${escapeHtml(task.title)}</div>
      ${task.description ? `<div class="task-desc">${escapeHtml(task.description)}</div>` : ''}
      <div class="task-date" style="font-size:0.75rem;color:var(--color-text-light);margin-top:0.25rem;">
        Criada em ${formattedDate}
      </div>
    </div>
    <span class="task-badge badge-${task.status}">${getStatusLabel(task.status)}</span>
    <button class="btn-delete" title="Excluir tarefa" aria-label="Excluir ${escapeHtml(task.title)}">✕</button>
  `;

  // Evento: clicar no card alterna o status da tarefa
  card.addEventListener('click', (e) => {
    // Não alterna se o clique foi no botão de excluir
    if (e.target.closest('.btn-delete')) return;
    toggleTaskStatus(task.id);
  });

  // Evento: clicar no botão de excluir remove a tarefa
  card.querySelector('.btn-delete').addEventListener('click', (e) => {
    e.stopPropagation(); // Previne que o clique propague para o card
    deleteTask(task.id);
  });

  return card;
}

/**
 * Retorna o texto exibido para um status.
 * @param {string} status - Status da tarefa
 * @returns {string} Label do status
 */
function getStatusLabel(status) {
  const labels = {
    [STATUSES.PENDENTE]: 'Pendente',
    [STATUSES.EM_ANDAMENTO]: 'Em Andamento',
    [STATUSES.CONCLUÍDO]: 'Concluído',
  };
  return labels[status] || status;
}

/**
 * Escapa caracteres HTML para prevenir XSS.
 * @param {string} text - Texto a ser escapado
 * @returns {string} Texto seguro
 */
function escapeHtml(text) {
  const div = document.createElement('div');
  div.textContent = text;
  return div.innerHTML;
}

// ==================== FUNÇÕES DE NOTIFICAÇÃO (Toast) ====================

/**
 * Exibe uma notificação toast na parte inferior da tela.
 * @param {string} message - Mensagem a ser exibida
 */
function showToast(message) {
  const toast = document.getElementById('toast');
  toast.textContent = message;
  toast.classList.remove('hidden');

  // Remove o toast após 3 segundos
  setTimeout(() => {
    toast.classList.add('hidden');
  }, 3000);
}

// ==================== EVENT LISTENERS ====================

/**
 * Configura todos os event listeners da aplicação.
 */
function setupEventListeners() {
  // ---- Formulário de adição de tarefas ----
  const form = document.getElementById('task-form');
  form.addEventListener('submit', (e) => {
    e.preventDefault();

    const titleInput = document.getElementById('task-title');
    const descInput = document.getElementById('task-desc');

    const title = titleInput.value.trim();
    const desc = descInput.value.trim();

    // Validação: título é obrigatório
    if (!title) {
      showToast('⚠️ O título da tarefa é obrigatório!');
      titleInput.focus();
      return;
    }

    // Cria a tarefa e reseta o formulário
    createTask(title, desc);
    form.reset();
    titleInput.focus();
    showToast('✅ Tarefa adicionada com sucesso!');

    // Re-renderiza a lista
    renderTasks();
  });

  // ---- Botões de filtro ----
  const filterButtons = document.querySelectorAll('.btn-filter');
  filterButtons.forEach((btn) => {
    btn.addEventListener('click', () => {
      // Remove classe active de todos os botões
      filterButtons.forEach((b) => b.classList.remove('active'));
      // Adiciona classe active ao botão clicado
      btn.classList.add('active');

      // Atualiza o filtro e re-renderiza
      currentFilter = btn.dataset.filter;
      renderTasks();
    });
  });

  // ---- Botão de limpar concluídos ----
  document.getElementById('clear-completed').addEventListener('click', () => {
    clearCompletedTasks();
  });
}

// ==================== INICIALIZAÇÃO ====================

/**
 * Inicializa a aplicação quando o DOM estiver pronto.
 */
function init() {
  setupEventListeners();
  renderTasks();
}

// Aguarda o DOM carregar antes de inicializar
document.addEventListener('DOMContentLoaded', init);
