## `app.js`

```javascript
/* ============================================================
   TASK MANAGER APPLICATION
   ============================================================
   Features:
     - Add / delete / toggle tasks
     - Group by status (Pending, In Progress, Completed)
     - Filter view by status
     - Persist to localStorage
   ============================================================ */

// ----------------------------
// 1. STATE & CONSTANTS
// ----------------------------

/** @type {Array<{ id: string, title: string, description: string, status: 'pending'|'in_progress'|'completed', createdAt: number }>} */
let tasks = [];

/** Current active filter ('all' | 'pending' | 'in_progress' | 'completed') */
let currentFilter = 'all';

const STORAGE_KEY = 'task_manager_tasks';

// ----------------------------
// 2. LOCAL STORAGE HELPERS
// ----------------------------

/** Load tasks from localStorage on startup */
function loadTasks() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (raw) {
      tasks = JSON.parse(raw);
    }
  } catch (e) {
    console.warn('Failed to load tasks from localStorage:', e);
    tasks = [];
  }
}

/** Save current tasks array to localStorage */
function saveTasks() {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(tasks));
  } catch (e) {
    console.warn('Failed to save tasks to localStorage:', e);
  }
}

// ----------------------------
// 3. DOM REFERENCES
// ----------------------------

const addTaskForm     = document.getElementById('add-task-form');
const taskTitleInput  = document.getElementById('task-title');
const taskDescInput   = document.getElementById('task-desc');
const filterButtons   = document.querySelectorAll('.btn-filter');
const emptyState      = document.getElementById('empty-state');

// Column lists (containers for each status group)
const taskLists = {
  pending:     document.getElementById('list-pending'),
  in_progress: document.getElementById('list-in_progress'),
  completed:   document.getElementById('list-completed'),
};

// Count badges
const countBadges = {
  pending:     document.getElementById('count-pending'),
  in_progress: document.getElementById('count-in_progress'),
  completed:   document.getElementById('count-completed'),
};

// ----------------------------
// 4. UTILITY FUNCTIONS
// ----------------------------

/** Generate a unique ID using timestamp + random suffix */
function generateId() {
  return Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
}

/** Cycle task status: pending → in_progress → completed → pending */
function cycleStatus(task) {
  const order = ['pending', 'in_progress', 'completed'];
  const nextIndex = (order.indexOf(task.status) + 1) % order.length;
  return order[nextIndex];
}

/** Get the human-readable label for a status */
function statusLabel(status) {
  const labels = {
    pending: 'Pending',
    in_progress: 'In Progress',
    completed: 'Completed',
  };
  return labels[status] || status;
}

// ----------------------------
// 5. TASK CRUD OPERATIONS
// ----------------------------

/**
 * Add a new task to the state and persist it.
 * @param {string} title
 * @param {string} description
 */
function addTask(title, description) {
  const task = {
    id: generateId(),
    title: title.trim(),
    description: description.trim(),
    status: 'pending', // new tasks always start as pending
    createdAt: Date.now(),
  };

  tasks.push(task);
  saveTasks();
}

/**
 * Delete a task by its ID.
 * @param {string} id
 */
function deleteTask(id) {
  tasks = tasks.filter((t) => t.id !== id);
  saveTasks();
}

/**
 * Toggle the next status for a task (click on card).
 * @param {string} id
 */
function toggleTaskStatus(id) {
  const task = tasks.find((t) => t.id === id);
  if (!task) return;

  task.status = cycleStatus(task);
  saveTasks();
}

// ----------------------------
// 6. RENDERING
// ----------------------------

/**
 * Render the entire board: update counts, filter tasks, and rebuild columns.
 */
function render() {
  // --- Update count badges (always show total per status) ---
  for (const status of Object.keys(countBadges)) {
    const count = tasks.filter((t) => t.status === status).length;
    countBadges[status].textContent = count;
  }

  // --- Determine which statuses to display based on filter ---
  let visibleStatuses;
  if (currentFilter === 'all') {
    visibleStatuses = ['pending', 'in_progress', 'completed'];
  } else {
    visibleStatuses = [currentFilter];
  }

  // --- Clear all columns ---
  for (const list of Object.values(taskLists)) {
    list.innerHTML = '';
  }

  // --- Group tasks by status and populate columns ---
  let totalVisible = 0;

  for (const status of visibleStatuses) {
    const filteredTasks = tasks.filter((t) => t.status === status);
    totalVisible += filteredTasks.length;

    for (const task of filteredTasks) {
      const card = createTaskCard(task);
      taskLists[status].appendChild(card);
    }
  }

  // --- Show / hide empty state ---
  if (totalVisible === 0) {
    emptyState.style.display = 'block';
  } else {
    emptyState.style.display = 'none';
  }
}

/**
 * Create a DOM element representing a single task card.
 * @param {{ id: string, title: string, description: string, status: string }} task
 * @returns {HTMLElement}
 */
function createTaskCard(task) {
  const card = document.createElement('div');
  card.className = `task-card ${task.status === 'completed' ? 'completed' : ''}`;
  card.dataset.id = task.id;

  // Clicking the card toggles its status
  card.addEventListener('click', (e) => {
    // Don't toggle if user clicked an action button
    if (e.target.closest('.btn-status') || e.target.closest('.btn-delete')) return;
    toggleTaskStatus(task.id);
  });

  // --- Status dot indicator ---
  const dot = document.createElement('span');
  dot.className = `status-dot ${task.status}`;
  card.appendChild(dot);

  // --- Title ---
  const titleEl = document.createElement('div');
  titleEl.className = 'task-title';
  titleEl.textContent = task.title;
  card.appendChild(titleEl);

  // --- Description (only if present) ---
  if (task.description) {
    const descEl = document.createElement('div');
    descEl.className = 'task-desc';
    descEl.textContent = task.description;
    card.appendChild(descEl);
  }

  // --- Action buttons row ---
  const actions = document.createElement('div');
  actions.className = 'task-actions';

  // "Next Status" button — cycles through statuses
  const nextBtn = document.createElement('button');
  nextBtn.className = 'btn btn-status';
  nextBtn.textContent = `→ ${statusLabel(cycleStatus(task))}`;
  nextBtn.title = `Move to ${statusLabel(cycleStatus(task))}`;
  nextBtn.addEventListener('click', () => toggleTaskStatus(task.id));
  actions.appendChild(nextBtn);

  // Delete button
  const delBtn = document.createElement('button');
  delBtn.className = 'btn btn-delete';
  delBtn.textContent = '✕ Delete';
  delBtn.title = 'Delete this task';
  delBtn.addEventListener('click', () => deleteTask(task.id));
  actions.appendChild(delBtn);

  card.appendChild(actions);

  return card;
}

// ----------------------------
// 7. EVENT LISTENERS
// ----------------------------

/** Handle adding a new task via the form */
addTaskForm.addEventListener('submit', (e) => {
  e.preventDefault();

  const title = taskTitleInput.value.trim();
  const desc  = taskDescInput.value.trim();

  if (!title) return; // HTML5 required handles most cases, but be safe

  addTask(title, desc);

  // Reset form and re-render
  addTaskForm.reset();
  render();

  // Focus back on title for rapid entry
  taskTitleInput.focus();
});

/** Handle filter button clicks */
filterButtons.forEach((btn) => {
  btn.addEventListener('click', () => {
    // Update active state across all filter buttons
    filterButtons.forEach((b) => b.classList.remove('active'));
    btn.classList.add('active');

    // Set new filter and re-render
    currentFilter = btn.dataset.filter;
    render();
  });
});

// ----------------------------
// 8. INITIALIZATION
// ----------------------------

/** Load persisted tasks and render the initial board */
function init() {
  loadTasks();
  render();
}

init();
```

