```javascript
/* ============================================================
   GERENCIADOR DE TAREFAS — app.js
   Aplicação completa em JavaScript puro (vanilla JS)
   ============================================================ */

// ==================== ESTADO DA APLICAÇÃO ====================
/**
 * Estado global da aplicação.
 * tasks: array de objetos tarefa
 * currentFilter: filtro ativo ('todas', 'pendente', 'em_andamento', 'concluído')
 */
const state = {
  tasks: [],
  currentFilter: 'todas'
};

// ==================== CONSTANTES ====================
/**
 * Chave usada no localStorage para persistência.
 */
const STORAGE_KEY = 'task_manager_tasks';

/**
 * Ordem dos status para exibição (topo → base).
 */
const STATUS_ORDER = ['pendente', 'em_andamento', 'concluído'];

/**
 * Configurações de exibição por status.
 */
const STATUS_CONFIG = {
  pendente:      { label: 'Pendentes',       icon: '⏳', color: '#f59e0b' },
  em_andamento:  { label: 'Em Andamento',    icon: '🔄', color: '#3b82f6' },
  concluído:     { label: 'Concluídos',      icon: '✅', color: '#10b981' }
};

// ==================== FUNÇÕES DE PERSISTÊNCIA (localStorage) ====================

/**
 * Salva o array de tarefas no localStorage.
 */
function saveTasks() {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(state.tasks));
}

/**
 * Carrega as tarefas do localStorage.
 * Retorna array vazio se não houver dados ou se houver erro de parse.
 */
function loadTasks() {
  try {
    const data = localStorage.getItem(STORAGE_KEY);
    return data ? JSON.parse(data) : [];
  } catch (error) {
    console.error('Erro ao carregar tarefas do localStorage:', error);
    return [];
  }
}

// ==================== FUNÇÕES DE CRIAÇÃO ====================

/**
 * Gera um ID único usando timestamp + random.
 */
function generateId() {
  return Date.now().toString(36) + Math.random().toString(36).substr(2, 5);
}

/**
 * Formata uma data para exibição em português (pt-BR).
 * @param {Date|string} date - Data a ser formatada
 * @returns {string} Data formatada
 */
function formatDate(date) {
  return new Date(date).toLocaleDateString('pt-BR', {
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit'
  });
}

/**
 * Cria uma nova tarefa a partir dos dados do formulário.
 * @param {string} title - Título da tarefa
 * @param {string} description - Descrição da tarefa
 * @returns {object} Tarefa criada
 */
function createTask(title, description) {
  const task = {
    id: generateId(),
    title: title.trim(),
    description: description.trim(),
    status: 'pendente', // Status inicial padrão
    createdAt: new Date().toISOString()
  };

  state.tasks.push(task);
  saveTasks();
  return task;
}

// ==================== FUNÇÕES DE ATUALIZAÇÃO ====================

/**
 * Alterna o status da tarefa ciclando entre os três estados.
 * Ordem: pendente → em_andamento → concluído → pendente
 * @param {string} taskId - ID da tarefa
 */
function toggleTaskStatus(taskId) {
  const task = state.tasks.find(t => t.id === taskId);
  if (!task) return;

  // Ciclo de status
  const cycle = {
    'pendente': 'em_andamento',
    'em_andamento': 'concluído',
    'concluído': 'pendente'
  };

  task.status = cycle[task.status];
  saveTasks();
  renderTasks();
}

/**
 * Exclui uma tarefa pelo ID com animação.
 * @param {string} taskId - ID da tarefa a ser excluída
 */
function deleteTask(taskId) {
  const taskElement = document.querySelector(`[data-task-id="${taskId}"]`);

  // Se o elemento existe, adiciona classe de animação antes de remover
  if (taskElement) {
    taskElement.classList.add('removing');
    taskElement.addEventListener('animationend', () => {
      state.tasks = state.tasks.filter(t => t.id !== taskId);
      saveTasks();
      renderTasks();
    }, { once: true });
  } else {
    // Fallback caso o elemento não seja encontrado
    state.tasks = state.tasks.filter(t => t.id !== taskId);
    saveTasks();
    renderTasks();
  }
}

// ==================== FUNÇÕES DE FILTRAGEM ====================

/**
 * Define o filtro ativo e re-renderiza a lista.
 * @param {string} filter - Filtro a ser aplicado
 */
function setFilter(filter) {
  state.currentFilter = filter;

  // Atualiza estado visual dos botões de filtro
  document.querySelectorAll('.btn-filter').forEach(btn => {
    btn.classList.toggle('active', btn.dataset.filter === filter);
  });

  renderTasks();
}

/**
 * Filtra as tarefas com base no filtro atual.
 * @returns {Array} Tarefas filtradas
 */
function getFilteredTasks() {
  if (state.currentFilter === 'todas') {
    return state.tasks;
  }
  return state.tasks.filter(t => t.status === state.currentFilter);
}

// ==================== FUNÇÕES DE RENDERIZAÇÃO ====================

/**
 * Atualiza os badges de contagem nos botões de filtro.
 */
function updateCounts() {
  document.getElementById('count-all').textContent = state.tasks.length;
  document.getElementById('count-pending').textContent =
    state.tasks.filter(t => t.status === 'pendente').length;
  document.getElementById('count-in-progress').textContent =
    state.tasks.filter(t => t.status === 'em_andamento').length;
  document.getElementById('count-completed').textContent =
    state.tasks.filter(t => t.status === 'concluído').length;
}

/**
 * Renderiza uma única tarefa como HTML.
 * @param {object} task - Objeto da tarefa
 * @returns {string} HTML da tarefa
 */
function renderTaskHTML(task) {
  return `
    <div class="task-item" data-task-id="${task.id}" data-status="${task.status}" title="Clique para alterar o status">
      <div class="task-checkbox"></div>
      <div class="task-content">
        <div class="task-title">${escapeHTML(task.title)}</div>
        ${task.description ? `<div class="task-description">${escapeHTML(task.description)}</div>` : ''}
        <div class="task-date">Criada em ${formatDate(task.createdAt)}</div>
      </div>
      <button class="btn-delete" data-delete-id="${task.id}" title="Excluir tarefa" aria-label="Excluir tarefa: ${escapeHTML(task.title)}">🗑️</button>
    </div>
  `;
}

/**
 * Renderiza todas as tarefas agrupadas por status.
 * Se o filtro estiver ativo, mostra apenas o grupo correspondente (ou todas).
 */
function renderTasks() {
  const container = document.getElementById('tasks-container');
  updateCounts();

  // Caso não haja tarefas
  if (state.tasks.length === 0) {
    container.innerHTML = renderEmptyState('Nenhuma tarefa cadastrada', 'Adicione sua primeira tarefa usando o formulário acima!');
    return;
  }

  // Determina quais grupos exibir com base no filtro
  let groupsToShow;
  if (state.currentFilter === 'todas') {
    groupsToShow = [...STATUS_ORDER];
  } else {
    groupsToShow = [state.currentFilter];
  }

  // Monta o HTML de cada grupo
  const groupHTMLs = groupsToShow.map(status => {
    const tasksInGroup = state.tasks.filter(t => t.status === status);
    const config = STATUS_CONFIG[status];

    if (tasksInGroup.length === 0) return '';

    return `
      <section class="task-group" data-status="${status}">
        <div class="task-group-header">
          <span>${config.icon}</span>
          <h3>${config.label}</h3>
          <span class="group-count">${tasksInGroup.length} tarefa${tasksInGroup.length > 1 ? 's' : ''}</span>
        </div>
        ${tasksInGroup.map(task => renderTaskHTML(task)).join('')}
      </section>
    `;
  }).join('');

  container.innerHTML = groupHTMLs || renderEmptyState(
    'Nenhuma tarefa neste filtro',
    'Tente selecionar outro filtro ou adicione novas tarefas.'
  );
}

/**
 * Renderiza o estado vazio (quando não há tarefas para exibir).
 * @param {string} title - Título da mensagem
 * @param {string} message - Descrição da mensagem
 * @returns {string} HTML do estado vazio
 */
function renderEmptyState(title, message) {
  return `
    <div class="empty-state">
      <div class="empty-icon">📭</div>
      <h3>${title}</h3>
      <p>${message}</p>
    </div>
  `;
}

/**
 * Escapa caracteres HTML para prevenir XSS.
 * @param {string} text - Texto a ser escapado
 * @returns {string} Texto com caracteres especiais escapados
 */
function escapeHTML(text) {
  const div = document.createElement('div');
  div.textContent = text;
  return div.innerHTML;
}

// ==================== EVENT LISTENERS ====================

/**
 * Configura o listener do formulário de adição.
 */
function setupFormListener() {
  const form = document.getElementById('task-form');

  form.addEventListener('submit', (event) => {
    event.preventDefault();

    const titleInput = document.getElementById('task-title');
    const descInput = document.getElementById('task-desc');

    const title = titleInput.value.trim();
    const description = descInput.value.trim();

    // Validação: título é obrigatório
    if (!title) {
      titleInput.focus();
      return;
    }

    // Cria a tarefa e reseta o formulário
    createTask(title, description);
    form.reset();
    titleInput.focus();

    // Feedback visual rápido (opcional)
    renderTasks();
  });
}

/**
 * Configura os listeners de clique no container de tarefas (event delegation).
 * Isso permite que novos elementos adicionados dinamicamente também respondam aos cliques.
 */
function setupTaskContainerListener() {
  const container = document.getElementById('tasks-container');

  container.addEventListener('click', (event) => {
    // Botão de excluir
    const deleteBtn = event.target.closest('.btn-delete');
    if (deleteBtn) {
      event.stopPropagation(); // Impede que o clique propague para o task-item
      const taskId = deleteBtn.dataset.deleteId;
      deleteTask(taskId);
      return;
    }

    // Clique na tarefa (alterna status)
    const taskItem = event.target.closest('.task-item');
    if (taskItem) {
      const taskId = taskItem.dataset.taskId;
      toggleTaskStatus(taskId);
    }
  });
}

/**
 * Configura os listeners dos botões de filtro.
 */
function setupFilterListeners() {
  const filterContainer = document.querySelector('.filter-buttons');

  filterContainer.addEventListener('click', (event) => {
    const btn = event.target.closest('.btn-filter');
    if (btn) {
      setFilter(btn.dataset.filter);
    }
  });
}

// ==================== INICIALIZAÇÃO ====================

/**
 * Inicializa a aplicação: carrega dados, configura eventos e renderiza.
 */
function init() {
  // Carrega tarefas salvas do localStorage
  state.tasks = loadTasks();

  // Configura todos os event listeners
  setupFormListener();
  setupTaskContainerListener();
  setupFilterListeners();

  // Renderiza a interface pela primeira vez
  renderTasks();
}

// Inicia a aplicação quando o DOM estiver pronto
document.addEventListener('DOMContentLoaded', init);
```

